// Tres libros no tienen artículo en árabe y llevan el título con que la propia
// Wikipedia árabe los nombra en el artículo del autor: «المخبرون المتوحشون»,
// «السهل يحترق» y «الغليان», que es como se publicó allí «Como agua para chocolate».
// Los tres se respaldan con el retrato del autor, así que ninguno queda sin imagen;
// solo «الألف» existe sin miniatura y también tira del autor. Tres desambiguadores son
// obligatorios porque el título a secas se lo lleva otro artículo: «النفق» es el túnel,
// «الحجلة» una desambiguación (ahí sí existe la novela de Cortázar, con retrato) y
// «الغليان» es el artículo de la ebullición.
