const PALABRAS_EN: Palabra[] = [
  { palabra: 'Serendipity', clase: 'noun', definicion: 'A valuable find that happens by accident, while looking for something else.', origen: 'Coined by Horace Walpole in 1754 after the Persian tale “The Three Princes of Serendip” —the old name of Sri Lanka— whose heroes kept discovering by chance what they were not looking for.', ejemplo: 'Finding that hidden café was pure serendipity.' },
  { palabra: 'Petrichor', clase: 'noun', definicion: 'The earthy scent that rain releases when it falls on dry ground.', origen: 'From the Greek petra (stone) and ichor (the fluid said to run through the veins of the gods); coined by two Australian geologists in 1964.', ejemplo: 'She opened the window to let the afternoon petrichor in.' },
  { palabra: 'Ineffable', clase: 'adjective', definicion: 'Too great or too beautiful to be put into words.', origen: 'From the Latin ineffabilis: in- (not) joined to effari (to utter); literally, what cannot be said.', ejemplo: 'He felt an ineffable joy when she walked in.' },
  { palabra: 'Ephemeral', clase: 'adjective', definicion: 'Lasting a very short time; fleeting.', origen: 'From the Greek ephemeros, “lasting only a day” (epi, upon, and hemera, day); it described flowers and insects born and gone within one turn of the sun.', ejemplo: 'The beauty of cherry blossom is ephemeral.' },
  { palabra: 'Resilience', clase: 'noun', definicion: 'The ability to adapt and bounce back in the face of adversity.', origen: 'From the Latin resilire, “to leap back”; it began in the physics of materials and jumped to psychology to name the strength of putting oneself back together.', ejemplo: 'Her resilience let her rebuild everything from scratch.' },
  { palabra: 'Mellifluous', clase: 'adjective', definicion: 'Sweet and smooth to hear, usually said of a voice.', origen: 'From the Latin mellifluus, “flowing with honey”, from mel (honey) and fluere (to flow).', ejemplo: 'The narrator had a mellifluous tone that lulled you to sleep.' },
  { palabra: 'Ataraxia', clase: 'noun', definicion: 'Serenity; a mind untroubled by worry.', origen: 'From the Greek ataraxia, “absence of disturbance”: the unshakeable calm pursued by Stoics and Epicureans.', ejemplo: 'He meditated each morning seeking the ataraxia of the Stoics.' },
  { palabra: 'Bonhomie', clase: 'noun', definicion: 'Good-natured friendliness and easy warmth of character.', origen: 'From the French bonhomie, derived from bonhomme, “good fellow”.', ejemplo: 'His bonhomie disarmed even the most suspicious.' },
  { palabra: 'Evanescent', clase: 'adjective', definicion: 'Vanishing almost as soon as it appears; barely there.', origen: 'From the Latin evanescere, “to vanish”, from ex- (out) and vanus (empty).', ejemplo: 'An evanescent smile crossed her face.' },
  { palabra: 'Aurora', clase: 'noun', definicion: 'The first light of morning; also the polar lights.', origen: 'From Aurora, the Roman goddess of dawn, who opened the gates of the sky for the sun each day.', ejemplo: 'They set out at the first aurora, when the city was still asleep.' },
  { palabra: 'Gloaming', clase: 'noun', definicion: 'The soft light of dusk, just after sunset.', origen: 'From the Old English glōmung, related to glow: the last glimmer of the day.', ejemplo: 'The gloaming turned the rooftops orange.' },
  { palabra: 'Halcyon', clase: 'adjective', definicion: 'Calm, peaceful and happy; said of a golden stretch of time.', origen: 'From the Greek halkyon (kingfisher): the ancients believed the bird nested at sea and stilled the winter waves for two weeks.', ejemplo: 'She still talks about the halcyon days of that summer.' },
  { palabra: 'Conviviality', clase: 'noun', definicion: 'The warmth of eating, drinking and talking together without hurry.', origen: 'From the Latin convivium (banquet), from con- (with) and vivere (to live): to live alongside others at the table.', ejemplo: 'The conviviality stretched on until it grew dark.' },
  { palabra: 'Matutinal', clase: 'adjective', definicion: 'Belonging to the early morning; happening at daybreak.', origen: 'From the Latin matutinus, from Matuta, the Roman goddess of the morning.', ejemplo: 'He keeps a matutinal habit of writing before anyone wakes.' },
  { palabra: 'Solace', clase: 'noun', definicion: 'Comfort given to someone in sorrow or distress.', origen: 'From the Latin solacium, from solari, “to console”.', ejemplo: 'She found solace in the company of her friends.' },
  { palabra: 'Chimera', clase: 'noun', definicion: 'Something imagined as possible that in truth is not.', origen: 'From the Greek Chimaira, the mythological monster with the head of a lion, the body of a goat and the tail of a serpent; from an impossible beast it came to name an impossible hope.', ejemplo: 'Living off the lottery is a chimera.' },
  { palabra: 'Utopia', clase: 'noun', definicion: 'An ideal plan or place, appealing but out of reach for now.', origen: 'Coined by Thomas More in 1516 for his imaginary island, from the Greek ou-topos, “no place”.', ejemplo: 'Utopia is useful: it keeps us walking, said Galeano.' },
  { palabra: 'Epiphany', clase: 'noun', definicion: 'A sudden realisation that makes everything fall into place.', origen: 'From the Greek epiphaneia, “a sudden appearance”; from religious use it came to name any unexpected flash of understanding.', ejemplo: 'She had an epiphany and rewrote the ending of her novel.' },
  { palabra: 'Perspicacious', clase: 'adjective', definicion: 'Quick to notice and understand what others miss.', origen: 'From the Latin perspicax, from perspicere, “to see through clearly”.', ejemplo: 'A perspicacious reader spotted the clue in the first chapter.' },
  { palabra: 'Taciturn', clase: 'adjective', definicion: 'Saying very little; reserved to the point of silence.', origen: 'From the Latin taciturnus, derived from tacere, “to be silent”.', ejemplo: 'He came back taciturn from the trip and nobody knew why.' },
  { palabra: 'Vehement', clase: 'adjective', definicion: 'Acting or speaking with great force and passion.', origen: 'From the Latin vehemens, “impetuous, carried away”: putting all one’s strength into what one feels or says.', ejemplo: 'He defended his idea in a vehement speech.' },
  { palabra: 'Idiosyncrasy', clase: 'noun', definicion: 'The distinctive traits that make a person or a people themselves.', origen: 'From the Greek idios (one’s own) and synkrasis (temperament, the mixture of the body’s humours).', ejemplo: 'The long lunch is part of our idiosyncrasy.' },
  { palabra: 'Parsimony', clase: 'noun', definicion: 'Extreme restraint in spending — or in the pace of doing anything.', origen: 'From the Latin parsimonia, “thrift”, from parcere, “to spare”.', ejemplo: 'He made the tea with an almost ceremonial parsimony.' },
  { palabra: 'Altruism', clase: 'noun', definicion: 'Care for the good of others, even at one’s own cost.', origen: 'From the French altruisme, coined by the philosopher Auguste Comte from autrui, “other people”, as the opposite of egoism.', ejemplo: 'He gave away the whole reward: pure altruism.' },
  { palabra: 'Empathy', clase: 'noun', definicion: 'The ability to step into someone else’s feelings and share them.', origen: 'From the Greek empatheia (en, in, and pathos, feeling); it is a calque of the German Einfühlung, “feeling into”.', ejemplo: 'She listened without judging, with an empathy that steadied him.' },
  { palabra: 'Nostalgia', clase: 'noun', definicion: 'A wistful ache for a place or a time now gone.', origen: 'From the Greek nostos (return) and algos (pain); coined in 1688 by the physician Johannes Hofer for the homesickness of soldiers far from home.', ejemplo: 'The smell of fresh bread filled him with nostalgia for his grandmother.' },
  { palabra: 'Ethereal', clase: 'adjective', definicion: 'So delicate and light that it seems not of this world.', origen: 'From the Greek aither, the pure upper region of the air where the ancients placed the gods.', ejemplo: 'The mist gave the woods an ethereal air.' },
  { palabra: 'Alpenglow', clase: 'noun', definicion: 'The rosy light that stains clouds and peaks at sunrise or sunset.', origen: 'A calque of the German Alpenglühen, “the glowing of the Alps”.', ejemplo: 'The alpenglow set the horizon on fire.' },
  { palabra: 'Oxymoron', clase: 'noun', definicion: 'Two words of opposite meaning put together ("deafening silence").', origen: 'From the Greek oxys (sharp) and moros (dull): the word is itself an oxymoron, joining the clever and the foolish.', ejemplo: '"Eternal instant" is her favourite oxymoron.' },
  { palabra: 'Palindrome', clase: 'noun', definicion: 'A word or phrase that reads the same backwards as forwards.', origen: 'From the Greek palin (again) and dromos (running): “running back” to where it started.', ejemplo: '"Never odd or even" is a classic palindrome.' },
  { palabra: 'Onomatopoeia', clase: 'noun', definicion: 'A word that imitates the sound of the thing it names.', origen: 'From the Greek onoma (name) and poiein (to make): “to make a name” out of a sound.', ejemplo: '"Whisper" is almost an onomatopoeia: it sounds like what it means.' },
  { palabra: 'Luminescence', clase: 'noun', definicion: 'Light given off without heat.', origen: 'From the Latin lumen (light) with the suffix -escence, marking a process under way: the cold light of fireflies and plankton.', ejemplo: 'The luminescence of the plankton painted the shore blue.' },
  { palabra: 'Nook', clase: 'noun', definicion: 'A small sheltered corner, tucked away from view.', origen: 'From the Middle English nok, “corner”; it survives in the pair “every nook and cranny”.', ejemplo: 'He knew every nook of the old quarter.' },
  { palabra: 'Vestibule', clase: 'noun', definicion: 'The covered entrance space between the street and the house.', origen: 'From the Latin vestibulum, the forecourt of a Roman house: the threshold between outside and home.', ejemplo: 'They left their bikes in the vestibule and ran inside.' },
  { palabra: 'Glimpse', clase: 'verb', definicion: 'To see something faintly or for an instant; to guess it from slight signs.', origen: 'From the Middle English glimsen, related to gleam: to catch a brief shine of something.', ejemplo: 'Through the haze he glimpsed the outline of the lighthouse.' },
  { palabra: 'Yearning', clase: 'noun', definicion: 'A tender, insistent longing for someone or something absent.', origen: 'From the Old English giernan, “to desire”: a wanting that stays even when nothing can be done about it.', ejemplo: 'He spoke of his village with yearning.' },
  { palabra: 'Pleiad', clase: 'noun', definicion: 'A brilliant group of people, especially in the arts, from one same age.', origen: 'From the Pleiades, the seven daughters of Atlas whom myth turned into stars; it later named groups of notable poets.', ejemplo: 'She belonged to the pleiad of poets of that decade.' },
  { palabra: 'Aubade', clase: 'noun', definicion: 'A poem or song about dawn, or about lovers parting at daybreak.', origen: 'From the French aubade, from aube (dawn), and that from the Latin albus, “white”.', ejemplo: 'The birds struck up their aubade.' },
  { palabra: 'Ruminate', clase: 'verb', definicion: 'To turn something over in the mind, again and again.', origen: 'From the Latin ruminari, “to chew the cud”: the thought is worked over like grass by cattle.', ejemplo: 'He ruminated on the offer all night.' },
  { palabra: 'Disquiet', clase: 'noun', definicion: 'A restlessness of the spirit; the loss of inner calm.', origen: 'From dis- (lack of) and quiet, from the Latin quietus; Fernando Pessoa made the word famous with his “Book of Disquiet”.', ejemplo: 'Waiting for the result filled her with disquiet.' },
]

const PALABRAS_PT: Palabra[] = [
  { palabra: 'Serendipidade', clase: 'substantivo', definicion: 'Descoberta valiosa que acontece por acaso, enquanto se procurava outra coisa.', origen: 'Cunhada por Horace Walpole em 1754 a partir do conto persa «Os Três Príncipes de Serendip» —antigo nome do Sri Lanka—, cujos heróis achavam por acaso o que não procuravam.', ejemplo: 'Encontrar aquele café escondido foi pura serendipidade.' },
  { palabra: 'Petricor', clase: 'substantivo', definicion: 'Cheiro de terra molhada que a chuva solta ao cair sobre o chão seco.', origen: 'Do grego petra (pedra) e ichor (o fluido que, segundo os mitos, corria nas veias dos deuses); foi cunhada por dois geólogos australianos em 1964.', ejemplo: 'Abriu a janela para deixar entrar o petricor da tarde.' },
  { palabra: 'Inefável', clase: 'adjetivo', definicion: 'Que é grande ou belo demais para caber em palavras.', origen: 'Do latim ineffabilis: o prefixo in- (não) unido a effari (dizer); literalmente, «aquilo que não pode ser dito».', ejemplo: 'Sentiu uma alegria inefável quando o viu chegar.' },
  { palabra: 'Efêmero', clase: 'adjetivo', definicion: 'Que dura muito pouco; passageiro.', origen: 'Do grego ephemeros, «que dura um só dia» (epi, sobre, e hemera, dia); dizia-se das flores e dos insetos que nascem e morrem numa jornada.', ejemplo: 'A beleza das cerejeiras em flor é efêmera.' },
  { palabra: 'Resiliência', clase: 'substantivo', definicion: 'Capacidade de se adaptar e se recompor diante da adversidade.', origen: 'Do latim resilire, «saltar para trás»; nasceu na física dos materiais e passou para a psicologia, para nomear a força de se remontar.', ejemplo: 'A resiliência dela a levou a reconstruir tudo do zero.' },
  { palabra: 'Melífluo', clase: 'adjetivo', definicion: 'Doce e suave de ouvir, quase sempre dito da voz.', origen: 'Do latim mellifluus, «que escorre mel», de mel (mel) e fluere (fluir).', ejemplo: 'A narradora tinha um tom melífluo que embalava.' },
  { palabra: 'Ataraxia', clase: 'substantivo', definicion: 'Serenidade; ausência de inquietação no ânimo.', origen: 'Do grego ataraxía, «ausência de perturbação»: era a calma imperturbável perseguida por estoicos e epicuristas.', ejemplo: 'Meditava toda manhã em busca da ataraxia dos estoicos.' },
  { palabra: 'Bonomia', clase: 'substantivo', definicion: 'Simplicidade afável e bondosa no trato.', origen: 'Do francês bonhomie, derivado de bonhomme, «bom homem».', ejemplo: 'A bonomia dele desarmava até o mais desconfiado.' },
  { palabra: 'Imarcescível', clase: 'adjetivo', definicion: 'Que não pode murchar nem se apagar.', origen: 'Do latim marcescere (murchar) com o prefixo negativo in-; usa-se sobretudo em sentido figurado, para o que não envelhece.', ejemplo: 'Guardava uma lembrança imarcescível daquele verão.' },
  { palabra: 'Alvorada', clase: 'substantivo', definicion: 'Primeira luz do dia, antes de o sol nascer.', origen: 'Derivada de alvor, «brancura», do latim albus: a claridade esbranquiçada que precede o amanhecer.', ejemplo: 'Saíram para caminhar na alvorada, com a cidade ainda dormindo.' },
  { palabra: 'Crepúsculo', clase: 'substantivo', definicion: 'Claridade incerta que há ao amanhecer ou ao anoitecer.', origen: 'Do latim crepusculum, diminutivo de creper, «escuro, duvidoso»: aquela luz ambígua entre o dia e a noite.', ejemplo: 'O crepúsculo tingiu de laranja os telhados.' },
  { palabra: 'Saudade', clase: 'substantivo', definicion: 'Lembrança terna de quem ou do que está longe, misturada com a vontade de ter aquilo de volta.', origen: 'Do latim solitas, «solidão»; é a palavra que o português guarda e que quase nenhuma outra língua traduz inteira.', ejemplo: 'Bateu uma saudade danada da casa da avó.' },
  { palabra: 'Cafuné', clase: 'substantivo', definicion: 'Carinho feito com a ponta dos dedos na cabeça de alguém.', origen: 'Do quimbundo kifunate, trazido pelo falar dos africanos escravizados no Brasil; virou o gesto de afeto mais brasileiro que existe.', ejemplo: 'Dormiu no sofá enquanto ela fazia cafuné.' },
  { palabra: 'Madrugar', clase: 'verbo', definicion: 'Levantar-se muito cedo, ao amanhecer ou antes.', origen: 'Do latim vulgar maturicare, de maturus, «maduro, no tempo certo»: fazer as coisas cedo, na hora.', ejemplo: 'Gosta de madrugar para escrever em silêncio.' },
  { palabra: 'Aconchego', clase: 'substantivo', definicion: 'Sensação de abrigo e calor que se sente num lugar ou nos braços de alguém.', origen: 'De aconchegar, «chegar para perto»; a palavra serve tanto para o agasalho quanto para o afeto.', ejemplo: 'Nada como o aconchego de casa num dia de chuva.' },
  { palabra: 'Quimera', clase: 'substantivo', definicion: 'Aquilo que se imagina possível e não é.', origen: 'Do grego Chímaira, o monstro mitológico com cabeça de leão, corpo de cabra e cauda de serpente; do bicho impossível passou a nomear a ilusão impossível.', ejemplo: 'Viver de loteria é uma quimera.' },
  { palabra: 'Utopia', clase: 'substantivo', definicion: 'Plano ou lugar ideal, atraente mas irrealizável por enquanto.', origen: 'Cunhada por Thomas More em 1516 para sua ilha imaginária, do grego ou-tópos, «não lugar».', ejemplo: 'A utopia serve para isso: para continuar caminhando, dizia Galeano.' },
  { palabra: 'Epifania', clase: 'substantivo', definicion: 'Revelação súbita que faz tudo se encaixar.', origen: 'Do grego epipháneia, «aparição repentina»; do uso religioso passou a nomear qualquer clarão inesperado de entendimento.', ejemplo: 'Teve uma epifania e reescreveu o final do romance.' },
  { palabra: 'Perspicaz', clase: 'adjetivo', definicion: 'Que percebe e entende depressa o que os outros deixam passar.', origen: 'Do latim perspicax, de perspicere, «ver através, enxergar com clareza».', ejemplo: 'Uma leitora perspicaz notou a pista no primeiro capítulo.' },
  { palabra: 'Taciturno', clase: 'adjetivo', definicion: 'Calado, silencioso; melancólico.', origen: 'Do latim taciturnus, derivado de tacere, «calar».', ejemplo: 'Voltou taciturno da viagem e ninguém soube por quê.' },
  { palabra: 'Veemente', clase: 'adjetivo', definicion: 'Que age ou fala com ímpeto e paixão.', origen: 'Do latim vehemens, «impetuoso, arrebatado»: quem põe toda a força no que sente ou diz.', ejemplo: 'Defendeu a ideia com um discurso veemente.' },
  { palabra: 'Idiossincrasia', clase: 'substantivo', definicion: 'Traços que fazem uma pessoa ou um povo serem quem são.', origen: 'Do grego ídios (próprio) e synkrasis (temperamento, a mistura dos humores do corpo).', ejemplo: 'O almoço demorado faz parte da nossa idiossincrasia.' },
  { palabra: 'Parcimônia', clase: 'substantivo', definicion: 'Moderação no gasto e, por extensão, lentidão calma no agir.', origen: 'Do latim parsimonia, «economia», de parcere, «poupar»; da medida no dinheiro passou à medida no ritmo.', ejemplo: 'Preparou o chá com uma parcimônia quase cerimonial.' },
  { palabra: 'Altruísmo', clase: 'substantivo', definicion: 'Cuidado com o bem alheio, mesmo à própria custa.', origen: 'Do francês altruisme, cunhado pelo filósofo Auguste Comte a partir de autrui, «o outro», como oposto do egoísmo.', ejemplo: 'Doou a recompensa inteira: puro altruísmo.' },
  { palabra: 'Empatia', clase: 'substantivo', definicion: 'Capacidade de entrar no sentimento do outro e compartilhá-lo.', origen: 'Do grego empátheia (en, dentro, e pathos, sentimento); é decalque do alemão Einfühlung, «sentir dentro de».', ejemplo: 'Ouviu sem julgar, com uma empatia que a acalmou.' },
  { palabra: 'Nostalgia', clase: 'substantivo', definicion: 'Tristeza doce por um tempo ou um lugar que já ficaram para trás.', origen: 'Do grego nóstos (regresso) e álgos (dor); foi cunhada em 1688 pelo médico Johannes Hofer para o mal dos soldados longe de casa.', ejemplo: 'O cheiro de pão quente deu nostalgia da avó.' },
  { palabra: 'Etéreo', clase: 'adjetivo', definicion: 'Tão leve e sutil que parece não ser deste mundo.', origen: 'Do grego aithér, a região superior e puríssima do ar onde os antigos punham os deuses.', ejemplo: 'A neblina dava à mata um ar etéreo.' },
  { palabra: 'Arrebol', clase: 'substantivo', definicion: 'Vermelho das nuvens iluminadas pelo sol ao nascer ou ao se pôr.', origen: 'Do latim rubor, «rubor, vermelhidão»: é o corar do céu nas duas pontas do dia.', ejemplo: 'O arrebol da tarde incendiava o horizonte.' },
  { palabra: 'Oximoro', clase: 'substantivo', definicion: 'Junção de duas palavras de sentido oposto («silêncio ensurdecedor»).', origen: 'Do grego oxys (agudo) e morós (tolo): a palavra é ela mesma um oximoro, pois junta o engenhoso e o bobo.', ejemplo: '«Instante eterno» é o oximoro preferido dele.' },
  { palabra: 'Palíndromo', clase: 'substantivo', definicion: 'Palavra ou frase que se lê igual de trás para a frente.', origen: 'Do grego pálin (de novo) e drómos (corrida): «que corre de volta» ao ponto de partida.', ejemplo: '«Socorram-me, subi no ônibus em Marrocos» é o palíndromo clássico.' },
  { palabra: 'Onomatopeia', clase: 'substantivo', definicion: 'Palavra que imita o som daquilo que nomeia.', origen: 'Do grego ónoma (nome) e poiein (fazer): «criar um nome» a partir do som da coisa.', ejemplo: '«Sussurro» é quase uma onomatopeia: soa como o que significa.' },
  { palabra: 'Luminescência', clase: 'substantivo', definicion: 'Emissão de luz que não vem do calor.', origen: 'Do latim lumen (luz) com o sufixo -escência, que marca um processo em curso: a luz fria dos vaga-lumes e do plâncton.', ejemplo: 'A luminescência do plâncton pintava a orla de azul.' },
  { palabra: 'Recanto', clase: 'substantivo', definicion: 'Canto escondido e tranquilo, afastado de tudo.', origen: 'De re- (reforço) e canto, «esquina»; serve tanto para um lugar quanto para as dobras da alma.', ejemplo: 'Conhecia cada recanto do bairro antigo.' },
  { palabra: 'Alpendre', clase: 'substantivo', definicion: 'Cobertura aberta na entrada da casa, onde se senta a ver a rua.', origen: 'Do árabe al-bandar, «o armazém coberto», segundo a etimologia mais aceita: o degrau com telhado entre a rua e a casa.', ejemplo: 'Deixaram as bicicletas no alpendre e entraram correndo.' },
  { palabra: 'Vislumbrar', clase: 'verbo', definicion: 'Ver algo de leve ou por um instante; adivinhar por sinais fracos.', origen: 'Do latim vix (apenas) e luminare (iluminar): «iluminar apenas», ver alguma coisa entre sombras.', ejemplo: 'Entre a bruma vislumbrou a silhueta do farol.' },
  { palabra: 'Anseio', clase: 'substantivo', definicion: 'Desejo intenso e insistente de algo que ainda não se tem.', origen: 'De ansiar, do latim anxiare, «apertar, sufocar»: o anseio aperta o peito de tanto querer.', ejemplo: 'Falava do futuro com um anseio contagiante.' },
  { palabra: 'Plêiade', clase: 'substantivo', definicion: 'Grupo brilhante de pessoas, sobretudo das letras, de uma mesma época.', origen: 'Das Plêiades, as sete filhas de Atlas que o mito transformou em estrelas; depois nomeou grupos de poetas notáveis.', ejemplo: 'Pertenceu à plêiade de poetas daquela década.' },
  { palabra: 'Alvíssaras', clase: 'substantivo', definicion: 'Prêmio ou festa que se dá a quem traz uma boa notícia.', origen: 'Do árabe al-bixāra, «a boa nova»; chegou ao português com os mensageiros que corriam a anunciar o que todos esperavam.', ejemplo: 'Alvíssaras: chegou a carta que esperávamos!' },
  { palabra: 'Matutar', clase: 'verbo', definicion: 'Ficar remoendo uma ideia, pensando nela sem parar.', origen: 'Derivada de matutino, «da manhã»: matutar era pensar de madrugada, quando a casa ainda está em silêncio.', ejemplo: 'Passou a noite matutando a proposta.' },
  { palabra: 'Desassossego', clase: 'substantivo', definicion: 'Falta de sossego; inquietação interior.', origen: 'Do prefixo des- (negação) e sossego, de sossegar; Fernando Pessoa a tornou célebre com o «Livro do Desassossego».', ejemplo: 'A espera do resultado lhe dava desassossego.' },
]

const PALABRAS_FR: Palabra[] = [
  { palabra: 'Sérendipité', clase: 'nom', definicion: 'Découverte heureuse que l’on fait par hasard, en cherchant tout autre chose.', origen: 'Forgée par Horace Walpole en 1754 d’après le conte persan « Les Trois Princes de Serendip » —ancien nom du Sri Lanka—, dont les héros trouvaient par hasard ce qu’ils ne cherchaient pas.', ejemplo: 'Tomber sur ce café caché, c’était de la pure sérendipité.' },
  { palabra: 'Pétrichor', clase: 'nom', definicion: 'Odeur de terre que la pluie libère en tombant sur un sol sec.', origen: 'Du grec petra (pierre) et ichor (le fluide qui coulait, disait-on, dans les veines des dieux) ; forgé par deux géologues australiens en 1964.', ejemplo: 'Elle a ouvert la fenêtre pour laisser entrer le pétrichor de l’après-midi.' },
  { palabra: 'Ineffable', clase: 'adjectif', definicion: 'Trop grand ou trop beau pour tenir dans des mots.', origen: 'Du latin ineffabilis : le préfixe in- (non) joint à effari (énoncer) ; littéralement, ce qui ne peut être dit.', ejemplo: 'Il a ressenti une joie ineffable en la voyant arriver.' },
  { palabra: 'Éphémère', clase: 'adjectif', definicion: 'Qui ne dure qu’un instant ; passager.', origen: 'Du grec ephemeros, « qui ne dure qu’un jour » (epi, sur, et hemera, jour) ; on le disait des fleurs et des insectes nés et morts en une seule journée.', ejemplo: 'La beauté des cerisiers en fleur est éphémère.' },
  { palabra: 'Résilience', clase: 'nom', definicion: 'Capacité à s’adapter et à se relever après le choc.', origen: 'Du latin resilire, « rebondir » ; née dans la physique des matériaux, elle est passée à la psychologie pour nommer la force de se recomposer.', ejemplo: 'Sa résilience lui a permis de tout rebâtir depuis zéro.' },
  { palabra: 'Chatoyant', clase: 'adjectif', definicion: 'Qui change de couleur selon la lumière, comme la soie ou l’œil du chat.', origen: 'De chatoyer, formé sur chat : l’œil du félin qui luit et se transforme dans l’obscurité.', ejemplo: 'La rivière avait des reflets chatoyants au couchant.' },
  { palabra: 'Ataraxie', clase: 'nom', definicion: 'Sérénité ; absence complète de trouble de l’âme.', origen: 'Du grec ataraxia, « absence de trouble » : le calme imperturbable que visaient stoïciens et épicuriens.', ejemplo: 'Il méditait chaque matin en cherchant l’ataraxie des stoïciens.' },
  { palabra: 'Bonhomie', clase: 'nom', definicion: 'Simplicité aimable et bienveillante du caractère.', origen: 'De bonhomme, « brave homme » : la manière d’être de celui qui ne se donne pas d’importance.', ejemplo: 'Sa bonhomie désarmait même les plus méfiants.' },
  { palabra: 'Impérissable', clase: 'adjectif', definicion: 'Qui ne peut ni se faner ni s’effacer.', origen: 'De périr, du latin perire, avec le préfixe négatif im- : ce que le temps n’use pas.', ejemplo: 'Il gardait un souvenir impérissable de cet été-là.' },
  { palabra: 'Aube', clase: 'nom', definicion: 'Première lueur du jour, avant le lever du soleil.', origen: 'Du latin alba, féminin de albus, « blanc » : la clarté blanchâtre qui précède le soleil.', ejemplo: 'Ils sont partis marcher à l’aube, quand la ville dormait encore.' },
  { palabra: 'Crépuscule', clase: 'nom', definicion: 'Lumière incertaine de l’aube ou du soir.', origen: 'Du latin crepusculum, diminutif de creper, « obscur, douteux » : cette clarté ambiguë entre le jour et la nuit.', ejemplo: 'Le crépuscule a teinté les toits d’orange.' },
  { palabra: 'Flâner', clase: 'verbe', definicion: 'Marcher sans but ni hâte, pour le seul plaisir de regarder.', origen: 'De l’ancien normand flana, « aller çà et là » ; Baudelaire en a fait une façon d’habiter la ville.', ejemplo: 'On a flâné le long des quais jusqu’à la nuit.' },
  { palabra: 'Retrouvailles', clase: 'nom', definicion: 'Joie de se revoir après une longue séparation.', origen: 'De retrouver ; le mot n’existe qu’au pluriel, parce qu’il faut être au moins deux.', ejemplo: 'Les retrouvailles à la gare ont duré un quart d’heure.' },
  { palabra: 'Dépaysement', clase: 'nom', definicion: 'Trouble heureux que l’on ressent hors de ses repères habituels.', origen: 'De dé- et pays : littéralement, être sorti de son pays — et de ses habitudes.', ejemplo: 'Trois rues plus loin, déjà le dépaysement.' },
  { palabra: 'Quiétude', clase: 'nom', definicion: 'Calme profond, sans agitation ni souci.', origen: 'Du latin quietudo, de quies, « repos » ; c’est le mot dont inquiétude est la négation.', ejemplo: 'Elle écrit à l’aube pour la quiétude de la maison.' },
  { palabra: 'Chimère', clase: 'nom', definicion: 'Ce que l’on imagine possible et qui ne l’est pas.', origen: 'Du grec Khimaira, le monstre à tête de lion, corps de chèvre et queue de serpent ; de la bête impossible on est passé au rêve impossible.', ejemplo: 'Vivre de la loterie est une chimère.' },
  { palabra: 'Utopie', clase: 'nom', definicion: 'Projet ou lieu idéal, séduisant mais hors d’atteinte pour l’instant.', origen: 'Forgée par Thomas More en 1516 pour son île imaginaire, du grec ou-topos, « en aucun lieu ».', ejemplo: 'L’utopie sert à ça : à continuer de marcher, disait Galeano.' },
  { palabra: 'Épiphanie', clase: 'nom', definicion: 'Illumination soudaine qui fait tout comprendre d’un coup.', origen: 'Du grec epiphaneia, « apparition soudaine » ; de l’usage religieux, le mot est passé à toute révélation intérieure.', ejemplo: 'Elle a eu une épiphanie et a réécrit la fin de son roman.' },
  { palabra: 'Perspicace', clase: 'adjectif', definicion: 'Qui saisit vite ce que les autres ne voient pas.', origen: 'Du latin perspicax, de perspicere, « voir à travers, voir clair ».', ejemplo: 'Une lectrice perspicace a repéré l’indice dès le premier chapitre.' },
  { palabra: 'Taciturne', clase: 'adjectif', definicion: 'Qui parle peu, jusqu’au silence.', origen: 'Du latin taciturnus, dérivé de tacere, « se taire ».', ejemplo: 'Il est revenu taciturne du voyage et personne n’a su pourquoi.' },
  { palabra: 'Véhément', clase: 'adjectif', definicion: 'Qui agit ou parle avec force et passion.', origen: 'Du latin vehemens, « emporté » : celui qui met toute son énergie dans ce qu’il ressent ou dit.', ejemplo: 'Il a défendu son idée dans un discours véhément.' },
  { palabra: 'Idiosyncrasie', clase: 'nom', definicion: 'Ensemble des traits qui font qu’une personne ou un peuple est lui-même.', origen: 'Du grec idios (propre) et synkrasis (tempérament, mélange des humeurs du corps).', ejemplo: 'Le repas qui s’éternise fait partie de notre idiosyncrasie.' },
  { palabra: 'Parcimonie', clase: 'nom', definicion: 'Réserve extrême dans la dépense — ou dans le rythme.', origen: 'Du latin parsimonia, « épargne », de parcere, « ménager » ; de la mesure dans l’argent à la mesure dans le geste.', ejemplo: 'Il préparait le thé avec une parcimonie presque cérémonielle.' },
  { palabra: 'Altruisme', clase: 'nom', definicion: 'Souci du bien d’autrui, même à ses propres dépens.', origen: 'Forgé par le philosophe Auguste Comte à partir d’autrui, comme contraire d’égoïsme.', ejemplo: 'Il a donné toute la récompense : pur altruisme.' },
  { palabra: 'Empathie', clase: 'nom', definicion: 'Capacité d’entrer dans le sentiment de l’autre et de le partager.', origen: 'Du grec empatheia (en, dans, et pathos, sentiment) ; c’est un calque de l’allemand Einfühlung, « sentir dedans ».', ejemplo: 'Elle a écouté sans juger, avec une empathie qui l’a apaisé.' },
  { palabra: 'Nostalgie', clase: 'nom', definicion: 'Mélancolie douce d’un temps ou d’un lieu désormais loin.', origen: 'Du grec nostos (retour) et algos (douleur) ; forgée en 1688 par le médecin Johannes Hofer pour le mal des soldats loin de chez eux.', ejemplo: 'L’odeur du pain chaud lui a donné la nostalgie de sa grand-mère.' },
  { palabra: 'Éthéré', clase: 'adjectif', definicion: 'Si léger et si subtil qu’il ne semble pas de ce monde.', origen: 'Du grec aither, la région haute et très pure de l’air où les anciens plaçaient les dieux.', ejemplo: 'La brume donnait à la forêt un air éthéré.' },
  { palabra: 'Rougeoiement', clase: 'nom', definicion: 'Lueur rouge des nuages ou des braises qui s’éteignent.', origen: 'De rougeoyer, formé sur rouge : la couleur qui ne brûle plus mais qui luit encore.', ejemplo: 'Le rougeoiement du couchant enflammait l’horizon.' },
  { palabra: 'Oxymore', clase: 'nom', definicion: 'Alliance de deux mots de sens contraire (« un silence assourdissant »).', origen: 'Du grec oxys (aigu) et moros (sot) : le mot est lui-même un oxymore, puisqu’il joint le fin et le bête.', ejemplo: '« Instant éternel » est son oxymore préféré.' },
  { palabra: 'Palindrome', clase: 'nom', definicion: 'Mot ou phrase qui se lit pareil dans les deux sens.', origen: 'Du grec palin (de nouveau) et dromos (course) : « qui court en sens inverse » vers son point de départ.', ejemplo: '« Ésope reste ici et se repose » est le palindrome classique.' },
  { palabra: 'Onomatopée', clase: 'nom', definicion: 'Mot qui imite le son de ce qu’il nomme.', origen: 'Du grec onoma (nom) et poiein (faire) : « fabriquer un nom » à partir d’un bruit.', ejemplo: '« Murmure » est presque une onomatopée : le mot sonne comme son sens.' },
  { palabra: 'Luminescence', clase: 'nom', definicion: 'Émission de lumière sans chaleur.', origen: 'Du latin lumen (lumière) avec le suffixe -escence, qui marque un processus en cours : la lumière froide des lucioles et du plancton.', ejemplo: 'La luminescence du plancton peignait la rive en bleu.' },
  { palabra: 'Recoin', clase: 'nom', definicion: 'Coin caché, à l’écart des regards.', origen: 'De re- (renforcement) et coin : le coin du coin, celui que l’on ne voit qu’une fois entré.', ejemplo: 'Il connaissait chaque recoin du vieux quartier.' },
  { palabra: 'Vestibule', clase: 'nom', definicion: 'Espace couvert entre la rue et le logement.', origen: 'Du latin vestibulum, l’avant-cour de la maison romaine : le seuil entre le dehors et le chez-soi.', ejemplo: 'Ils ont laissé les vélos dans le vestibule et sont entrés en courant.' },
  { palabra: 'Entrevoir', clase: 'verbe', definicion: 'Voir à peine, un instant ; deviner à de faibles indices.', origen: 'De entre- (à demi) et voir : voir entre deux ombres, sans tout à fait voir.', ejemplo: 'Dans la brume, il a entrevu la silhouette du phare.' },
  { palabra: 'Espiègle', clase: 'adjectif', definicion: 'Malicieux sans méchanceté, joueur.', origen: 'De Till l’Espiègle (Ulenspiegel), le farceur des contes flamands, dont le nom est devenu un adjectif français.', ejemplo: 'Elle a un sourire espiègle quand elle prépare une surprise.' },
  { palabra: 'Pléiade', clase: 'nom', definicion: 'Groupe brillant de personnes, surtout de lettres, d’une même époque.', origen: 'Des Pléiades, les sept filles d’Atlas changées en étoiles ; le mot a ensuite désigné des groupes de poètes.', ejemplo: 'Elle appartenait à la pléiade de poètes de cette décennie.' },
  { palabra: 'Aubade', clase: 'nom', definicion: 'Chant du matin, ou chant des amants qui se quittent au jour levant.', origen: 'De aube, du latin albus, « blanc » : la musique que l’on donnait sous les fenêtres au petit matin.', ejemplo: 'Les oiseaux ont entonné leur aubade.' },
  { palabra: 'Ruminer', clase: 'verbe', definicion: 'Retourner sans fin la même pensée dans sa tête.', origen: 'Du latin ruminari, « remâcher » : la pensée travaillée comme l’herbe par les bêtes.', ejemplo: 'Il a ruminé la proposition toute la nuit.' },
  { palabra: 'Intranquillité', clase: 'nom', definicion: 'Perte du calme intérieur ; inquiétude sourde et sans objet.', origen: 'De tranquillité avec le préfixe privatif in- ; le mot s’est imposé en français par le « Livre de l’intranquillité » de Fernando Pessoa.', ejemplo: 'L’attente du résultat lui donnait une sourde intranquillité.' },
]

const PALABRAS_DE: Palabra[] = [
  { palabra: 'Serendipität', clase: 'Substantiv', definicion: 'Ein glücklicher Fund, den man zufällig macht, während man etwas ganz anderes sucht.', origen: 'Von Horace Walpole 1754 nach dem persischen Märchen „Die drei Prinzen von Serendip“ geprägt — Serendip ist der alte Name Sri Lankas; seine Helden fanden stets, was sie nicht suchten.', ejemplo: 'Dieses versteckte Café zu finden war reine Serendipität.' },
  { palabra: 'Petrichor', clase: 'Substantiv', definicion: 'Der erdige Duft, den Regen freisetzt, wenn er auf trockenen Boden fällt.', origen: 'Aus dem Griechischen petra (Stein) und ichor (das Fluidum, das der Sage nach in den Adern der Götter floss); 1964 von zwei australischen Geologen geprägt.', ejemplo: 'Sie öffnete das Fenster für den Petrichor des Nachmittags.' },
  { palabra: 'Unsagbar', clase: 'Adjektiv', definicion: 'So groß oder so schön, dass keine Worte dafür reichen.', origen: 'Von sagen mit der Vorsilbe un-; die alte Lehnübersetzung des lateinischen ineffabilis, „was nicht gesagt werden kann“.', ejemplo: 'Als sie hereinkam, empfand er eine unsagbare Freude.' },
  { palabra: 'Vergänglich', clase: 'Adjektiv', definicion: 'Was nur kurz bleibt und wieder verschwindet.', origen: 'Von vergehen, „vorübergehen“; das Barock machte daraus sein großes Thema, die Vanitas.', ejemplo: 'Die Schönheit der Kirschblüte ist vergänglich.' },
  { palabra: 'Resilienz', clase: 'Substantiv', definicion: 'Die Fähigkeit, sich anzupassen und nach einem Schlag wieder aufzustehen.', origen: 'Vom lateinischen resilire, „zurückspringen“; der Begriff stammt aus der Werkstoffphysik und wanderte in die Psychologie.', ejemplo: 'Ihre Resilienz ließ sie alles von vorn aufbauen.' },
  { palabra: 'Wohllaut', clase: 'Substantiv', definicion: 'Der angenehme Klang einer Stimme, eines Verses, einer ganzen Sprache.', origen: 'Aus wohl und Laut; eine Wortschöpfung der Aufklärung als deutsche Antwort auf das griechische Euphonie.', ejemplo: 'Die Erzählerin hatte einen Wohllaut, der einen einschlafen ließ.' },
  { palabra: 'Ataraxie', clase: 'Substantiv', definicion: 'Gelassenheit; ein Gemüt, das nichts mehr aufwühlt.', origen: 'Vom griechischen ataraxia, „Unerschütterlichkeit“: das Ziel von Stoikern und Epikureern.', ejemplo: 'Er meditierte jeden Morgen und suchte die Ataraxie der Stoiker.' },
  { palabra: 'Gemütlichkeit', clase: 'Substantiv', definicion: 'Die behagliche Wärme eines Ortes oder einer Runde, in der es niemand eilig hat.', origen: 'Von Gemüt, dem inneren Empfinden; das Wort gilt als unübersetzbar und wurde in viele Sprachen entlehnt.', ejemplo: 'Nach dem Regen war die Gemütlichkeit in der Küche vollkommen.' },
  { palabra: 'Fernweh', clase: 'Substantiv', definicion: 'Der Schmerz, woanders sein zu wollen: das Gegenstück zum Heimweh.', origen: 'Aus fern und Weh, gebildet nach dem Muster von Heimweh; belegt seit dem 19. Jahrhundert, der Zeit der großen Reisen.', ejemplo: 'Beim Blick auf die Karte packte ihn das Fernweh.' },
  { palabra: 'Morgenröte', clase: 'Substantiv', definicion: 'Das rote Licht am Himmel, kurz bevor die Sonne aufgeht.', origen: 'Aus Morgen und Röte; Nietzsche gab einem seiner Bücher diesen Titel, weil das Wort auch den Anfang von etwas meint.', ejemplo: 'Sie brachen in der Morgenröte auf, die Stadt schlief noch.' },
  { palabra: 'Zwielicht', clase: 'Substantiv', definicion: 'Das ungewisse Licht zwischen Tag und Nacht.', origen: 'Aus zwie- (zweifach) und Licht: die Stunde, in der zwei Lichter zugleich gelten und keines ganz.', ejemplo: 'Im Zwielicht wurden die Dächer orange.' },
  { palabra: 'Waldeinsamkeit', clase: 'Substantiv', definicion: 'Das stille Alleinsein im Wald, halb Trost und halb Schauer.', origen: 'Von Ludwig Tieck 1797 erfunden und von der Romantik übernommen; kaum eine Sprache übersetzt das Wort in einem Stück.', ejemplo: 'Nach einer Stunde Weg stellte sich die Waldeinsamkeit ein.' },
  { palabra: 'Geborgenheit', clase: 'Substantiv', definicion: 'Das Gefühl, sicher und gehalten zu sein.', origen: 'Von bergen, „in Sicherheit bringen“ — dasselbe Verb, das auch in verbergen steckt.', ejemplo: 'Bei ihr fand er eine Geborgenheit, die er lange vermisst hatte.' },
  { palabra: 'Schwelgen', clase: 'Verb', definicion: 'Sich einer Freude ganz hingeben, ohne auf die Zeit zu achten.', origen: 'Vom mittelhochdeutschen swelgen, „schlucken“: aus dem Genuss im Mund wurde der Genuss im Gemüt.', ejemplo: 'Sie schwelgten den ganzen Abend in Erinnerungen.' },
  { palabra: 'Feierabend', clase: 'Substantiv', definicion: 'Der Teil des Tages, der nach der Arbeit einem selbst gehört.', origen: 'Ursprünglich der Vorabend eines Feiertags, an dem früher Schluss gemacht wurde; heute meint es das tägliche Ende der Arbeit.', ejemplo: 'Er macht Feierabend und lässt das Handy liegen.' },
  { palabra: 'Hirngespinst', clase: 'Substantiv', definicion: 'Eine Vorstellung, die man für möglich hält und die keine ist.', origen: 'Aus Hirn und Gespinst, dem Gewebe der Spinne: ein Gedanke, den der Kopf selbst gesponnen hat.', ejemplo: 'Vom Lotto zu leben ist ein Hirngespinst.' },
  { palabra: 'Utopie', clase: 'Substantiv', definicion: 'Ein idealer Plan oder Ort, verlockend und vorerst unerreichbar.', origen: '1516 von Thomas Morus für seine erfundene Insel geprägt, aus dem Griechischen ou-topos, „kein Ort“.', ejemplo: 'Die Utopie ist dazu da, dass wir weitergehen, sagte Galeano.' },
  { palabra: 'Geistesblitz', clase: 'Substantiv', definicion: 'Der plötzliche Einfall, nach dem alles zusammenpasst.', origen: 'Aus Geist und Blitz: der Gedanke kommt so schnell und so hell wie ein Wetterleuchten.', ejemplo: 'Sie hatte einen Geistesblitz und schrieb den Schluss neu.' },
  { palabra: 'Scharfsinnig', clase: 'Adjektiv', definicion: 'Wer schnell bemerkt und versteht, was andere übersehen.', origen: 'Aus scharf und Sinn; die Lehnübersetzung des lateinischen perspicax, „durchschauend“.', ejemplo: 'Eine scharfsinnige Leserin fand den Hinweis im ersten Kapitel.' },
  { palabra: 'Wortkarg', clase: 'Adjektiv', definicion: 'Wer wenig sagt, ohne dabei unfreundlich zu sein.', origen: 'Aus Wort und karg, „sparsam“: jemand, der mit Worten haushält.', ejemplo: 'Er kam wortkarg von der Reise zurück, und niemand wusste warum.' },
  { palabra: 'Ungestüm', clase: 'Adjektiv', definicion: 'Wer mit voller Kraft und ohne Bremse handelt oder spricht.', origen: 'Vom mittelhochdeutschen ungestüeme, „ohne Ruhe“, verwandt mit Sturm.', ejemplo: 'Er verteidigte seine Idee in einer ungestümen Rede.' },
  { palabra: 'Eigenart', clase: 'Substantiv', definicion: 'Die Züge, die einen Menschen oder ein Volk unverwechselbar machen.', origen: 'Aus eigen und Art; die deutsche Entsprechung des griechischen Wortes Idiosynkrasie.', ejemplo: 'Das lange Mittagessen gehört zu unserer Eigenart.' },
  { palabra: 'Bedächtig', clase: 'Adjektiv', definicion: 'Langsam und überlegt in jedem Handgriff.', origen: 'Von bedenken: wer erst denkt und dann greift, bewegt sich von selbst langsamer.', ejemplo: 'Er goss den Tee bedächtig auf, fast feierlich.' },
  { palabra: 'Selbstlosigkeit', clase: 'Substantiv', definicion: 'Die Sorge um das Wohl anderer, auch auf eigene Kosten.', origen: 'Aus selbst und -los: wer sich selbst aus der Rechnung nimmt. Die deutsche Antwort auf den Altruismus von Auguste Comte.', ejemplo: 'Er gab die ganze Belohnung weiter: reine Selbstlosigkeit.' },
  { palabra: 'Einfühlungsvermögen', clase: 'Substantiv', definicion: 'Die Gabe, in das Gefühl eines anderen hineinzugehen.', origen: 'Von Einfühlung, einem Begriff der deutschen Ästhetik um 1900; das englische empathy ist eine Übersetzung davon.', ejemplo: 'Sie hörte ohne Urteil zu, mit einem Einfühlungsvermögen, das ihn beruhigte.' },
  { palabra: 'Heimweh', clase: 'Substantiv', definicion: 'Der Schmerz, fern von zu Hause zu sein.', origen: 'Aus Heim und Weh; ein Schweizer Wort, das der Arzt Johannes Hofer 1688 als Nostalgie ins Lateinische übersetzte.', ejemplo: 'Der Duft von frischem Brot machte ihm Heimweh.' },
  { palabra: 'Ätherisch', clase: 'Adjektiv', definicion: 'So fein und leicht, dass es nicht von dieser Welt scheint.', origen: 'Vom griechischen aither, der reinen oberen Luft, in der die Alten die Götter wohnen ließen.', ejemplo: 'Der Nebel gab dem Wald etwas Ätherisches.' },
  { palabra: 'Alpenglühen', clase: 'Substantiv', definicion: 'Das rote Leuchten der Berge kurz nach Sonnenuntergang.', origen: 'Aus Alpen und glühen; das Englische hat das Wort als alpenglow übernommen, weil es kein eigenes dafür hatte.', ejemplo: 'Das Alpenglühen setzte den Horizont in Brand.' },
  { palabra: 'Oxymoron', clase: 'Substantiv', definicion: 'Zwei Wörter mit entgegengesetztem Sinn nebeneinander („ohrenbetäubende Stille“).', origen: 'Aus dem Griechischen oxys (scharf) und moros (dumm): das Wort ist selbst ein Oxymoron, denn es verbindet das Kluge und das Törichte.', ejemplo: '„Ewiger Augenblick“ ist ihr liebstes Oxymoron.' },
  { palabra: 'Palindrom', clase: 'Substantiv', definicion: 'Wort oder Satz, der rückwärts gelesen derselbe bleibt.', origen: 'Aus dem Griechischen palin (wieder) und dromos (Lauf): „was zurückläuft“ zu seinem Anfang.', ejemplo: '„Lagerregal“ ist ein Palindrom wie aus dem Lehrbuch.' },
  { palabra: 'Lautmalerei', clase: 'Substantiv', definicion: 'Ein Wort, das den Klang dessen nachahmt, was es benennt.', origen: 'Aus Laut und Malerei: mit Lauten malen. Die deutsche Übersetzung des griechischen Onomatopöie.', ejemplo: '„Säuseln“ ist fast reine Lautmalerei: es klingt wie das, was es meint.' },
  { palabra: 'Lumineszenz', clase: 'Substantiv', definicion: 'Licht, das ohne Wärme entsteht.', origen: 'Vom lateinischen lumen (Licht) mit der Endung -eszenz, die einen laufenden Vorgang anzeigt: das kalte Licht der Glühwürmchen und des Planktons.', ejemplo: 'Die Lumineszenz des Planktons färbte das Ufer blau.' },
  { palabra: 'Schlupfwinkel', clase: 'Substantiv', definicion: 'Ein verstecktes Eckchen, in das man sich zurückzieht.', origen: 'Aus schlüpfen und Winkel: der Winkel, in den man schlüpft, wenn man nicht gefunden werden will.', ejemplo: 'Er kannte jeden Schlupfwinkel der Altstadt.' },
  { palabra: 'Hausflur', clase: 'Substantiv', definicion: 'Der überdachte Gang zwischen Haustür und Wohnung.', origen: 'Aus Haus und Flur, „ebene Fläche“: die Schwelle zwischen Straße und Zuhause.', ejemplo: 'Sie stellten die Räder in den Hausflur und liefen hinein.' },
  { palabra: 'Erahnen', clase: 'Verb', definicion: 'Etwas nur undeutlich sehen oder aus kleinen Zeichen erraten.', origen: 'Von ahnen mit der Vorsilbe er-, die das Gelingen anzeigt: die Ahnung, die gerade noch trifft.', ejemplo: 'Im Nebel erahnte er die Umrisse des Leuchtturms.' },
  { palabra: 'Sehnsucht', clase: 'Substantiv', definicion: 'Das schmerzhafte Verlangen nach etwas, das fehlt oder vielleicht nie da war.', origen: 'Aus sehnen und Sucht (im alten Sinn von „Krankheit“): die Krankheit des Sehnens. Die Romantik machte sie zum Lebensgefühl.', ejemplo: 'Er sprach von seinem Dorf mit Sehnsucht.' },
  { palabra: 'Plejade', clase: 'Substantiv', definicion: 'Eine glänzende Gruppe von Menschen einer Zeit, meist Dichter.', origen: 'Nach den Plejaden, den sieben Töchtern des Atlas, die der Mythos zu Sternen machte.', ejemplo: 'Sie gehörte zur Plejade der Dichter jenes Jahrzehnts.' },
  { palabra: 'Tagelied', clase: 'Substantiv', definicion: 'Lied vom Abschied der Liebenden im Morgengrauen.', origen: 'Aus Tag und Lied: die Gattung der Minnesänger, verwandt mit der provenzalischen alba.', ejemplo: 'Die Vögel stimmten ihr Tagelied an.' },
  { palabra: 'Grübeln', clase: 'Verb', definicion: 'Einen Gedanken immer wieder umwälzen, ohne zu einem Ende zu kommen.', origen: 'Verwandt mit graben: im Kopf herumgraben wie in der Erde.', ejemplo: 'Er grübelte die ganze Nacht über das Angebot.' },
  { palabra: 'Unruhe', clase: 'Substantiv', definicion: 'Der Verlust der inneren Ruhe; eine leise Beunruhigung ohne Namen.', origen: 'Aus un- und Ruhe; Fernando Pessoa machte das Wort mit dem „Buch der Unruhe“ berühmt.', ejemplo: 'Das Warten auf das Ergebnis erfüllte sie mit Unruhe.' },
]

const PALABRAS_IT: Palabra[] = [
  { palabra: 'Serendipità', clase: 'sostantivo', definicion: 'Scoperta felice che capita per caso, mentre si cercava tutt’altro.', origen: 'Coniata da Horace Walpole nel 1754 dalla fiaba persiana «I tre principi di Serendippo» —antico nome dello Sri Lanka—, i cui eroi trovavano per caso ciò che non cercavano.', ejemplo: 'Trovare quel caffè nascosto è stata pura serendipità.' },
  { palabra: 'Petricore', clase: 'sostantivo', definicion: 'Odore di terra che la pioggia libera cadendo sul suolo asciutto.', origen: 'Dal greco petra (pietra) e ichor (il fluido che, secondo il mito, scorreva nelle vene degli dèi); coniata da due geologi australiani nel 1964.', ejemplo: 'Aprì la finestra per far entrare il petricore del pomeriggio.' },
  { palabra: 'Ineffabile', clase: 'aggettivo', definicion: 'Troppo grande o troppo bello per stare dentro le parole.', origen: 'Dal latino ineffabilis: il prefisso in- (non) unito a effari (dire); alla lettera, ciò che non si può dire.', ejemplo: 'Provò una gioia ineffabile nel vederlo arrivare.' },
  { palabra: 'Effimero', clase: 'aggettivo', definicion: 'Che dura pochissimo; passeggero.', origen: 'Dal greco ephemeros, «che dura un solo giorno» (epi, sopra, e hemera, giorno); si diceva dei fiori e degli insetti nati e morti in una giornata.', ejemplo: 'La bellezza dei ciliegi in fiore è effimera.' },
  { palabra: 'Resilienza', clase: 'sostantivo', definicion: 'Capacità di adattarsi e di rialzarsi dopo un colpo.', origen: 'Dal latino resilire, «rimbalzare»; nasce nella fisica dei materiali ed è passata alla psicologia per nominare la forza di rimettersi insieme.', ejemplo: 'La sua resilienza le ha permesso di ricostruire tutto da zero.' },
  { palabra: 'Mellifluo', clase: 'aggettivo', definicion: 'Dolce e morbido da ascoltare, detto quasi sempre della voce.', origen: 'Dal latino mellifluus, «che stilla miele», da mel (miele) e fluere (scorrere).', ejemplo: 'La narratrice aveva un tono mellifluo che cullava.' },
  { palabra: 'Atarassia', clase: 'sostantivo', definicion: 'Serenità; assenza di turbamento dell’animo.', origen: 'Dal greco ataraxía, «assenza di turbamento»: la calma imperturbabile cercata da stoici ed epicurei.', ejemplo: 'Meditava ogni mattina cercando l’atarassia degli stoici.' },
  { palabra: 'Bonomia', clase: 'sostantivo', definicion: 'Semplicità cordiale e benevola nel modo di fare.', origen: 'Dal francese bonhomie, da bonhomme, «brav’uomo».', ejemplo: 'La sua bonomia disarmava anche il più diffidente.' },
  { palabra: 'Imperituro', clase: 'aggettivo', definicion: 'Che non può appassire né spegnersi.', origen: 'Dal latino perire con il prefisso negativo in-; si usa soprattutto in senso figurato, per ciò che il tempo non consuma.', ejemplo: 'Conservava un ricordo imperituro di quell’estate.' },
  { palabra: 'Alba', clase: 'sostantivo', definicion: 'Prima luce del giorno, prima che il sole si alzi.', origen: 'Dal latino alba, femminile di albus, «bianco»: il chiarore biancastro che precede il sole.', ejemplo: 'Uscirono a camminare all’alba, con la città ancora addormentata.' },
  { palabra: 'Crepuscolo', clase: 'sostantivo', definicion: 'Luce incerta dell’alba o della sera.', origen: 'Dal latino crepusculum, diminutivo di creper, «oscuro, dubbio»: quella luce ambigua tra il giorno e la notte.', ejemplo: 'Il crepuscolo tinse di arancione i tetti.' },
  { palabra: 'Meriggio', clase: 'sostantivo', definicion: 'L’ora del mezzogiorno pieno, quando il caldo ferma ogni cosa.', origen: 'Dal latino meridies, «mezzo del giorno»; Montale ne fece uno dei luoghi della poesia italiana.', ejemplo: 'Nel meriggio d’agosto non si muoveva una foglia.' },
  { palabra: 'Abbiocco', clase: 'sostantivo', definicion: 'Sonnolenza improvvisa che arriva dopo un buon pranzo.', origen: 'Dal romanesco abbioccarsi, «accasciarsi come una chioccia»; da Roma è passato a tutta l’Italia e altrove non ha traduzione.', ejemplo: 'Dopo la lasagna è arrivato l’abbiocco.' },
  { palabra: 'Albeggiare', clase: 'verbo', definicion: 'Farsi giorno; cominciare a schiarire.', origen: 'Da alba: il verbo che il giorno usa per nascere. Vale anche in senso figurato, per un’idea che comincia.', ejemplo: 'Partirono appena albeggiava, in silenzio.' },
  { palabra: 'Struggimento', clase: 'sostantivo', definicion: 'Desiderio così intenso da fare quasi male.', origen: 'Da struggere, dal latino destruere, «disfare»: il desiderio consuma chi lo prova, come la cera al fuoco.', ejemplo: 'Parlava di quel viaggio con struggimento.' },
  { palabra: 'Chimera', clase: 'sostantivo', definicion: 'Ciò che si immagina possibile e non lo è.', origen: 'Dal greco Chímaira, il mostro con testa di leone, corpo di capra e coda di serpente; dalla bestia impossibile all’illusione impossibile.', ejemplo: 'Vivere di lotteria è una chimera.' },
  { palabra: 'Utopia', clase: 'sostantivo', definicion: 'Progetto o luogo ideale, attraente ma per ora irrealizzabile.', origen: 'Coniata da Tommaso Moro nel 1516 per la sua isola immaginaria, dal greco ou-topos, «nessun luogo».', ejemplo: 'L’utopia serve a questo: a farci camminare, diceva Galeano.' },
  { palabra: 'Epifania', clase: 'sostantivo', definicion: 'Rivelazione improvvisa che fa capire tutto in un colpo.', origen: 'Dal greco epipháneia, «apparizione improvvisa»; dall’uso religioso è passata a ogni lampo di comprensione.', ejemplo: 'Ebbe un’epifania e riscrisse il finale del romanzo.' },
  { palabra: 'Perspicace', clase: 'aggettivo', definicion: 'Che coglie in fretta ciò che agli altri sfugge.', origen: 'Dal latino perspicax, da perspicere, «vedere attraverso, vedere chiaro».', ejemplo: 'Una lettrice perspicace notò l’indizio nel primo capitolo.' },
  { palabra: 'Taciturno', clase: 'aggettivo', definicion: 'Che parla poco, fino al silenzio.', origen: 'Dal latino taciturnus, da tacere, «stare zitto».', ejemplo: 'Tornò taciturno dal viaggio e nessuno seppe perché.' },
  { palabra: 'Veemente', clase: 'aggettivo', definicion: 'Che agisce o parla con impeto e passione.', origen: 'Dal latino vehemens, «trascinato»: chi mette tutta la forza in ciò che sente o dice.', ejemplo: 'Difese la sua idea con un discorso veemente.' },
  { palabra: 'Idiosincrasia', clase: 'sostantivo', definicion: 'L’insieme dei tratti che fanno di una persona o di un popolo se stessi.', origen: 'Dal greco ídios (proprio) e synkrasis (temperamento, la mescolanza degli umori del corpo).', ejemplo: 'Il pranzo che si allunga fa parte della nostra idiosincrasia.' },
  { palabra: 'Parsimonia', clase: 'sostantivo', definicion: 'Misura nello spendere e, per estensione, lentezza calma nel fare.', origen: 'Dal latino parsimonia, «risparmio», da parcere, «risparmiare»; dalla misura nel denaro a quella nel gesto.', ejemplo: 'Preparò il tè con una parsimonia quasi cerimoniale.' },
  { palabra: 'Altruismo', clase: 'sostantivo', definicion: 'Cura del bene altrui, anche a proprie spese.', origen: 'Dal francese altruisme, coniato dal filosofo Auguste Comte su autrui, «gli altri», come contrario di egoismo.', ejemplo: 'Regalò l’intera ricompensa: puro altruismo.' },
  { palabra: 'Empatia', clase: 'sostantivo', definicion: 'Capacità di entrare nel sentimento dell’altro e di condividerlo.', origen: 'Dal greco empátheia (en, dentro, e pathos, sentimento); è un calco del tedesco Einfühlung, «sentire dentro».', ejemplo: 'Ascoltò senza giudicare, con un’empatia che lo rasserenò.' },
  { palabra: 'Nostalgia', clase: 'sostantivo', definicion: 'Malinconia dolce per un tempo o un luogo ormai lontani.', origen: 'Dal greco nóstos (ritorno) e álgos (dolore); coniata nel 1688 dal medico Johannes Hofer per il male dei soldati lontani da casa.', ejemplo: 'L’odore del pane caldo gli diede nostalgia della nonna.' },
  { palabra: 'Etereo', clase: 'aggettivo', definicion: 'Così lieve e sottile da non sembrare di questo mondo.', origen: 'Dal greco aithér, la regione alta e purissima dell’aria dove gli antichi collocavano gli dèi.', ejemplo: 'La nebbia dava al bosco un’aria eterea.' },
  { palabra: 'Vermiglio', clase: 'aggettivo', definicion: 'Di un rosso vivo e caldo, come le nuvole all’ultimo sole.', origen: 'Dal latino vermiculus, il piccolo verme da cui si ricavava la tinta scarlatta più preziosa del Medioevo.', ejemplo: 'Il cielo vermiglio della sera incendiava l’orizzonte.' },
  { palabra: 'Ossimoro', clase: 'sostantivo', definicion: 'Unione di due parole di senso opposto («silenzio assordante»).', origen: 'Dal greco oxys (acuto) e morós (sciocco): la parola è essa stessa un ossimoro, perché unisce l’arguto e lo stolto.', ejemplo: '«Istante eterno» è il suo ossimoro preferito.' },
  { palabra: 'Palindromo', clase: 'sostantivo', definicion: 'Parola o frase che si legge uguale nei due sensi.', origen: 'Dal greco pálin (di nuovo) e drómos (corsa): «che corre all’indietro» verso il punto di partenza.', ejemplo: '«I topi non avevano nipoti» è il palindromo classico.' },
  { palabra: 'Onomatopea', clase: 'sostantivo', definicion: 'Parola che imita il suono di ciò che nomina.', origen: 'Dal greco ónoma (nome) e poiein (fare): «fabbricare un nome» a partire da un rumore.', ejemplo: '«Fruscio» è quasi un’onomatopea: suona come ciò che significa.' },
  { palabra: 'Luminescenza', clase: 'sostantivo', definicion: 'Emissione di luce che non nasce dal calore.', origen: 'Dal latino lumen (luce) con il suffisso -escenza, che indica un processo in corso: la luce fredda delle lucciole e del plancton.', ejemplo: 'La luminescenza del plancton dipingeva di blu la riva.' },
  { palabra: 'Anfratto', clase: 'sostantivo', definicion: 'Cavità o angolo nascosto, difficile da raggiungere.', origen: 'Dal latino anfractus, «curva, giro»: la piega del terreno che nasconde un riparo. Si usa anche per le pieghe di un discorso.', ejemplo: 'Conosceva ogni anfratto del quartiere vecchio.' },
  { palabra: 'Androne', clase: 'sostantivo', definicion: 'Il passaggio coperto tra il portone e il cortile di casa.', origen: 'Dal greco andrón, la sala degli uomini nella casa antica; oggi è la soglia in ombra tra la strada e le scale.', ejemplo: 'Lasciarono le bici nell’androne ed entrarono di corsa.' },
  { palabra: 'Intravedere', clase: 'verbo', definicion: 'Vedere appena, per un istante; indovinare da piccoli segni.', origen: 'Da intra- (in mezzo) e vedere: vedere tra due ombre, senza vedere del tutto.', ejemplo: 'Nella foschia intravide la sagoma del faro.' },
  { palabra: 'Rimpianto', clase: 'sostantivo', definicion: 'Dolore dolce per ciò che è finito o non si è fatto.', origen: 'Da rimpiangere, da piangere: il pianto che torna quando la cosa è già passata.', ejemplo: 'Parlava del suo paese con rimpianto.' },
  { palabra: 'Pleiade', clase: 'sostantivo', definicion: 'Gruppo brillante di persone, soprattutto di lettere, di una stessa epoca.', origen: 'Dalle Pleiadi, le sette figlie di Atlante che il mito trasformò in stelle; poi nominò gruppi di poeti illustri.', ejemplo: 'Apparteneva alla pleiade di poeti di quel decennio.' },
  { palabra: 'Mattutino', clase: 'sostantivo', definicion: 'Canto o preghiera che si intona alle prime luci.', origen: 'Dal latino matutinus, da Matuta, la dea romana del mattino; era la prima ora dell’ufficio monastico, cantata ancora al buio.', ejemplo: 'Gli uccelli intonarono il loro mattutino.' },
  { palabra: 'Rimuginare', clase: 'verbo', definicion: 'Rigirare un pensiero nella testa senza mai posarlo.', origen: 'Legata al latino rumigare, «ruminare»: il pensiero masticato di nuovo, come l’erba dai bovini.', ejemplo: 'Rimuginò l’offerta tutta la notte.' },
  { palabra: 'Inquietudine', clase: 'sostantivo', definicion: 'Perdita della calma interiore; un’agitazione senza nome.', origen: 'Dal latino inquietudo, da quies, «quiete»; Fernando Pessoa la rese celebre con il «Libro dell’inquietudine».', ejemplo: 'L’attesa del risultato le dava inquietudine.' },
]

// En japonés la lectura no se adivina (澪標, 玉響), así que va en `clase`, que es
// el subtítulo de la ficha: «名詞（みおつくし）».
const PALABRAS_JA: Palabra[] = [
  { palabra: '木漏れ日', clase: '名詞（こもれび）', definicion: '木の葉のあいだからこぼれ落ちてくる日の光のことです。', origen: '「木」「漏れる」「日」を重ねただけの言葉ですが、光そのものではなく光が葉を通り抜けるという出来事に名前をつけている点が珍しく、訳しにくい日本語としてよく挙げられます。', ejemplo: '並木道の木漏れ日が、歩くたびに揺れていました。' },
  { palabra: '侘び寂び', clase: '名詞（わびさび）', definicion: '質素なもの、古びたものに宿る静かな美しさのことです。', origen: '満たされない心細さを表す「侘び」と、時が経って寂れていくさまを表す「寂び」が室町時代の茶の湯で結び合い、欠けや傷を欠点ではなく味わいとして見る目のことになりました。', ejemplo: 'ひびの入った茶碗にこそ侘び寂びを感じます。' },
  { palabra: '幽玄', clase: '名詞（ゆうげん）', definicion: '言い尽くせない、奥深くほのかな趣のことです。', origen: 'もとは中国の仏典で「奥深くて計り知れない」を意味しましたが、能を大成した世阿弥が芸の理想として使い、霧の向こうに何かがあると感じさせる美しさを指すようになりました。', ejemplo: '霧に沈む山の姿には幽玄なところがあります。' },
  { palabra: '花明かり', clase: '名詞（はなあかり）', definicion: '満開の桜が、夜でもあたりをほのかに明るく見せることです。', origen: '和歌の世界では「花」は桜を指します。灯りのないはずの夜道が白く浮かび上がる、その錯覚のような明るさに名前をつけた春の季語です。', ejemplo: '花明かりの下を、灯りもつけずに帰りました。' },
  { palabra: '夕凪', clase: '名詞（ゆうなぎ）', definicion: '夕方、海風と陸風が入れ替わるあいだ、風がぴたりとやむことです。', origen: '「凪」は「風」と「止」を合わせて日本で作られた漢字です。朝に起こる同じ現象は「朝凪」と呼びます。', ejemplo: '夕凪の海は、鏡のように静かでした。' },
  { palabra: '常しえ', clase: '名詞（とこしえ）', definicion: 'いつまでも変わらずに続くこと。永遠のことです。', origen: '「常」は変わらないさま、「しえ」は状態を表す古い語尾で、万葉集の時代から使われてきました。', ejemplo: '常しえに続くものなど、そう多くはありません。' },
  { palabra: '名残', clase: '名詞（なごり）', definicion: '過ぎ去ったあとに、まだ残っている気配のことです。', origen: 'もとは「波残り」で、引いた波が砂に残していく跡のことでした。人が去ったあとの気配にも同じ言葉を使うようになりました。', ejemplo: '部屋にはまだ夏の名残がありました。' },
  { palabra: '陽炎', clase: '名詞（かげろう）', definicion: '強い日差しで地面近くの空気が揺らぎ、景色がゆらゆらと見える現象です。', origen: '燃え立つ光を意味した古語「かぎろひ」が変化した言葉で、つかまえられないもの、はかないものの例えにも使われます。', ejemplo: '線路の先が陽炎で溶けて見えました。' },
  { palabra: '逢魔が時', clase: '名詞（おうまがとき）', definicion: '昼と夜の境目、あたりが薄暗くなる夕暮れどきのことです。', origen: '「魔に逢う時刻」の意味です。人の顔が見分けにくくなるこの時間には怪しいものが現れると考えられていました。「大禍時」とも書きます。', ejemplo: '逢魔が時になると、子どもたちは家に帰されました。' },
  { palabra: '一期一会', clase: '名詞（いちごいちえ）', definicion: 'この出会いは一生に一度きりだと思って向き合うことです。', origen: '千利休の教えを弟子の山上宗二が書き残した言葉で、同じ茶会は二度と開けないという心構えを表します。', ejemplo: '旅先の会話も一期一会だと思うと、聞き方が変わります。' },
  { palabra: '積読', clase: '名詞（つんどく）', definicion: '買った本を読まないまま積み上げておくことです。', origen: '「積んでおく」と「読書」をかけた明治時代の言葉遊びで、皮肉というより、いつか読むという楽しみを含んだ響きがあります。', ejemplo: '積読の山が、また一冊高くなりました。' },
  { palabra: '物の哀れ', clase: '名詞（もののあわれ）', definicion: '移ろうものに触れたときに、しみじみと胸を打たれる感じのことです。', origen: '江戸時代の国学者・本居宣長が『源氏物語』を読み解くために立てた言葉で、悲しみとも喜びともつかない、静かに動く心を指します。', ejemplo: '散っていく花に物の哀れを覚えます。' },
  { palabra: '奥ゆかしい', clase: '形容詞（おくゆかしい）', definicion: '慎み深く、もっと知りたいと思わせる品のよさがあることです。', origen: '「奥」へ「行かしい」、つまり奥のほうへ心が引かれるという意味から生まれました。控えめさがそのまま魅力になるという発想が形になった言葉です。', ejemplo: '何も言わずに手を貸すところが奥ゆかしい人です。' },
  { palabra: '花筏', clase: '名詞（はないかだ）', definicion: '散った桜の花びらが水面に集まり、筏のように流れていくことです。', origen: '花びらの帯を筏に見立てた春の季語です。同じ名前の植物もあり、葉の真ん中に花をつける姿から名づけられました。', ejemplo: '堀いっぱいに花筏が広がっていました。' },
  { palabra: '風薫る', clase: '動詞（かぜかおる）', definicion: '初夏の風が、若葉の匂いを運んでくることです。', origen: 'もともとは花の香りを運ぶ風を指しましたが、俳諧では初夏の季語として定まり、青葉の匂いのほうを指すようになりました。', ejemplo: '風薫る朝に、窓を大きく開けました。' },
  { palabra: '蛍雪', clase: '名詞（けいせつ）', definicion: '苦労を重ねて学ぶことです。', origen: '中国の故事から来ています。灯油が買えず、車胤は蛍の光で、孫康は雪の明るさで本を読んだと伝えられます。「蛍雪の功」の形でよく使われます。', ejemplo: '蛍雪の日々が、いまの仕事を支えています。' },
  { palabra: '玉響', clase: '名詞（たまゆら）', definicion: 'ほんの一瞬。かすかなあいだのことです。', origen: '万葉集に見える古い言葉で、玉と玉が触れ合ってかすかに鳴る、その短さから来たといわれます。', ejemplo: '雨の前に、玉響の静けさがありました。' },
  { palabra: '東雲', clase: '名詞（しののめ）', definicion: '夜明けに東の空がほのかに明るくなるころのことです。', origen: '明かり取りの窓に張った「篠の目」から光が差し込むさまが語源とされ、のちに東の雲という漢字が当てられました。', ejemplo: '東雲の空が、少しずつ色を変えていきました。' },
  { palabra: '黄昏', clase: '名詞（たそがれ）', definicion: '日が落ちて、あたりが薄暗くなるころのことです。', origen: '「誰そ彼」、つまり「あれは誰だろう」と尋ねなければ顔が分からない時刻、という問いかけがそのまま言葉になりました。', ejemplo: '黄昏の川べりを、ゆっくり歩いて帰りました。' },
  { palabra: '山紫水明', clase: '名詞（さんしすいめい）', definicion: '山は紫にかすみ、水は澄んで見える、美しい自然の眺めのことです。', origen: '江戸後期の文人・頼山陽が京都の書斎を「山紫水明処」と名づけたことで広まった四字熟語です。', ejemplo: '山紫水明の土地で、一週間だけ暮らしてみたいです。' },
  { palabra: '時雨', clase: '名詞（しぐれ）', definicion: '晩秋から初冬にかけて、降ってはやみを繰り返す通り雨のことです。', origen: '「過ぐる」が変化した語といわれ、通り過ぎていく雨という意味です。心変わりやはかなさの比喩にも使われてきました。', ejemplo: '時雨が来て、五分でまた晴れました。' },
  { palabra: '花冷え', clase: '名詞（はなびえ）', definicion: '桜が咲くころに、急に寒さが戻ることです。', origen: '「花」は桜のことです。せっかく咲いたのに冷え込むという、少し恨めしい気持ちまで含んだ春の季語です。', ejemplo: '花冷えの夜は、上着をもう一枚出します。' },
  { palabra: '佇まい', clase: '名詞（たたずまい）', definicion: '人や場所が、そこにあるだけで漂わせている雰囲気のことです。', origen: '「佇む」、つまりじっと立ち止まっているさまから生まれた名詞で、動きではなく在り方そのものを指します。', ejemplo: '古い喫茶店の佇まいが好きでした。' },
  { palabra: '静謐', clase: '名詞（せいひつ）', definicion: '物音ひとつなく、心まで落ち着くような静けさのことです。', origen: '「静」も「謐」も静かという意味で、同じ意味の漢字を重ねることで静けさの度合いを強めています。', ejemplo: '朝の図書館には静謐がありました。' },
  { palabra: '余韻', clase: '名詞（よいん）', definicion: '音が消えたあとも残る響き。転じて、終わったあとに残る味わいのことです。', origen: '「余」は残り、「韻」は響きです。鐘の音が消えてなお空気に残る震えから、読み終えた本の後味までを指すようになりました。', ejemplo: '最後の一行の余韻で、しばらく動けませんでした。' },
  { palabra: '面影', clase: '名詞（おもかげ）', definicion: '記憶のなかに浮かぶ、その人や昔の姿のことです。', origen: '「面」は顔、「影」は古語では光や姿を意味しました。目の前にないのに見えてしまう顔、という成り立ちです。', ejemplo: 'この町には、まだ祖母の面影があります。' },
  { palabra: '淡雪', clase: '名詞（あわゆき）', definicion: '春先に降る、すぐ消えてしまう薄い雪のことです。', origen: '「淡い雪」がそのまま名詞になったもので、積もらずに解けるはかなさから、消えやすいものの比喩にも使われます。', ejemplo: '朝の淡雪は、昼には残っていませんでした。' },
  { palabra: '睦まじい', clase: '形容詞（むつまじい）', definicion: '仲がよく、そばにいるだけで心が温かいことです。', origen: '親しみ合うという動詞「睦む」から生まれました。旧暦一月の別名「睦月」も、人が集まって睦み合う月という説があります。', ejemplo: '睦まじい二人を見ていると、こちらまで嬉しくなります。' },
  { palabra: '麗らか', clase: '形容動詞（うららか）', definicion: '空が晴れて日ざしが柔らかく、心まで明るくなるようすです。', origen: '曇りのない明るさを表す古語「うら」から生まれ、天気だけでなく声や気分にも使われます。春の季語です。', ejemplo: '麗らかな午後で、洗濯物がよく乾きました。' },
  { palabra: '潮騒', clase: '名詞（しおさい）', definicion: '潮が満ちてくるときの、波のざわめきのことです。', origen: '「騒」は古語でざわめきのことです。三島由紀夫の小説の題名になってから、広く知られるようになりました。', ejemplo: '窓を開けると、遠くに潮騒が聞こえました。' },
  { palabra: '山笑う', clase: '動詞（やまわらう）', definicion: '春になって木々が芽吹き、山全体が明るくにぎやかに見えることです。', origen: '中国・北宋の画家、郭熙が四季の山を書き分けた言葉のひとつで、俳句の春の季語になりました。夏は「山滴る」、秋は「山粧う」、冬は「山眠る」です。', ejemplo: '山笑う季節になり、遠出がしたくなりました。' },
  { palabra: '雪明かり', clase: '名詞（ゆきあかり）', definicion: '積もった雪が光を返して、夜でもぼんやり明るいことです。', origen: '灯りのない夜道でも足元が見えるという、雪国の暮らしから生まれた言葉です。', ejemplo: '雪明かりだけで、家まで帰れました。' },
  { palabra: '泡沫', clase: '名詞（うたかた）', definicion: '水面にできてはすぐ消える泡。転じて、はかないもののことです。', origen: '『方丈記』の「よどみに浮かぶうたかたは……」で知られる古語で、漢字はあとから意味に合わせて当てられました。', ejemplo: '泡沫のような計画でしたが、話しているあいだは楽しかったです。' },
  { palabra: '言霊', clase: '名詞（ことだま）', definicion: '言葉そのものに宿ると信じられてきた力のことです。', origen: '万葉集には日本を「言霊の幸はふ国」と詠んだ歌があります。口に出した言葉が現実を動かすという古い考え方です。', ejemplo: '言霊を信じて、弱音は口に出さないようにしています。' },
  { palabra: '慈しむ', clase: '動詞（いつくしむ）', definicion: '弱いものを、大切に思ってかわいがることです。', origen: '神聖で犯しがたいという意味の古語「厳し」から生まれ、上から下へ注ぐ深い情愛を指します。', ejemplo: '借りた本を慈しむように扱う人でした。' },
  { palabra: '手向け', clase: '名詞（たむけ）', definicion: '旅立つ人や亡くなった人に、心を込めて何かを供えることです。', origen: '峠道で「手を向けて」神に供え物をした習わしが語源で、「峠」という国字もここから生まれたといわれます。', ejemplo: '一輪だけ、手向けの花を置いてきました。' },
  { palabra: '曙', clase: '名詞（あけぼの）', definicion: '夜がほのぼのと明けはじめるころのことです。', origen: '「明け」と、ほのかに明るいという意味の「ぼの」が結びついた言葉です。『枕草子』の「春はあけぼの」で知られます。', ejemplo: '曙の光が、障子を白くしていきました。' },
  { palabra: '心待ち', clase: '名詞（こころまち）', definicion: '何かを楽しみにして、そっと待つことです。', origen: '「心」で待つ、つまり口には出さずに内側で待つという成り立ちです。', ejemplo: '手紙の返事を心待ちにしていました。' },
  { palabra: '微睡む', clase: '動詞（まどろむ）', definicion: '浅く、少しのあいだ眠ることです。', origen: '「目蓋とろむ」が縮まった語といわれ、眠りに落ちきらない、ふわりとした状態を指します。', ejemplo: '電車の窓辺で、三駅ぶん微睡みました。' },
  { palabra: '澪標', clase: '名詞（みおつくし）', definicion: '船が通れる深い水路を示すために、水中に立てておく杭のことです。', origen: '「澪つ串」、つまり水路の杭という意味です。「身を尽くし」と音が重なるため、和歌では身を捧げる恋の比喩として繰り返し詠まれました。', ejemplo: '澪標のように、誰かの目印になれたらと思います。' },
]

const PALABRAS_ZH: Palabra[] = [
  { palabra: '团圆', clase: '名词', definicion: '分开的家人重新聚到一起，尤其指节日里一家人围着同一张桌子。', origen: '“团”是圆，“圆”也是圆；两个圆叠在一起，说的是人，也是月。中秋赏月吃圆饼，用的正是这个意思。', ejemplo: '忙了一整年，图的就是年夜饭那顿团圆。' },
  { palabra: '岁月静好', clase: '成语', definicion: '日子平平稳稳地过着，没有惊涛骇浪，也不觉得亏欠。', origen: '出自《诗经·郑风·女曰鸡鸣》的“琴瑟在御，莫不静好”，原写夫妻相处的和睦，今天多用来形容一段安稳的时光。', ejemplo: '阳台上晒着被子，猫在脚边打盹，岁月静好。' },
  { palabra: '惊蛰', clase: '名词', definicion: '二十四节气之一，春雷初响、蛰伏的虫子被唤醒的那几天。', origen: '“蛰”是藏起来冬眠，“惊”是被雷声惊动。古人认为第一声春雷是把大地叫醒的信号。', ejemplo: '过了惊蛰，院子里的虫鸣一天比一天密。' },
  { palabra: '烟火气', clase: '名词', definicion: '日常生活里柴米油盐的那股热闹味道。', origen: '“烟火”原指人家做饭升起的炊烟；加一个“气”字，就成了有人在好好过日子的证据，与冷清、清高相对。', ejemplo: '菜市场最有烟火气，走一圈心就定了。' },
  { palabra: '意境', clase: '名词', definicion: '作品在字句和笔墨之外留出的、让人自己去体会的那层天地。', origen: '唐代诗论里已有雏形，王国维在《人间词话》中把它定为评判诗词的最高标准：写景要能生情，情又要能落回景。', ejemplo: '这幅画留白最多的地方，意境也最深。' },
  { palabra: '缘分', clase: '名词', definicion: '人与人相遇、相处的那份说不清来由的机缘。', origen: '“缘”本是佛家语，指促成一件事的条件；民间把它接到人身上，于是相识、错过和重逢都有了解释。', ejemplo: '隔了十年在异国的车站遇见，只能说是缘分。' },
  { palabra: '婉约', clase: '形容词', definicion: '含蓄柔和，把话说得曲折而不直白。', origen: '明代张綖把宋词分为“婉约”与“豪放”两派，前者以李清照、柳永为代表，讲究一唱三叹、欲说还休。', ejemplo: '她的字也婉约，笔画收得很轻。' },
  { palabra: '空灵', clase: '形容词', definicion: '通透而不着痕迹，像有回声一样留着余地。', origen: '“空”是没有堵塞，“灵”是活。原是画论和诗论的用语，形容笔墨疏淡却神气流动。', ejemplo: '那段独唱很空灵，唱完了屋里还静着。' },
  { palabra: '皎洁', clase: '形容词', definicion: '明亮而干净，多半用来说月光。', origen: '“皎”从“白”，本义是月色分明；“洁”是没有杂质。两个字连用，几乎是专为月亮准备的。', ejemplo: '昨夜月色皎洁，路灯都显得多余。' },
  { palabra: '氤氲', clase: '形容词', definicion: '烟气、雾气或香气缓缓弥漫、交融的样子。', origen: '出自《易经》的“天地氤氲，万物化醇”，原指天地二气交合；后来专写那层看得见却摸不着的缭绕。', ejemplo: '茶汤刚沏好，热气氤氲了半张桌子。' },
  { palabra: '缱绻', clase: '形容词', definicion: '情意深厚、缠在一起舍不得分开。', origen: '《诗经·大雅·民劳》有“无纵诡随，以谨缱绻”。两个字都是绞丝旁，写的正是线缠住线的那种牵连。', ejemplo: '信里没有一句直白的话，却字字缱绻。' },
  { palabra: '眷恋', clase: '动词', definicion: '对人或地方深深留恋，不忍离开。', origen: '“眷”是回头看，“恋”是舍不得。合起来就是走了几步还要回头的那个动作。', ejemplo: '离开住了八年的城市，还是眷恋那条河。' },
  { palabra: '怅惘', clase: '形容词', definicion: '心里空落落的，说不上是失望还是失落。', origen: '“怅”是失意，“惘”是茫然。两种情绪都不激烈，合在一起正好是那种钝钝的难过。', ejemplo: '老照片翻到一半，忽然有点怅惘。' },
  { palabra: '熹微', clase: '形容词', definicion: '天刚亮时那一点微弱的光。', origen: '陶渊明《归去来兮辞》有“问征夫以前路，恨晨光之熹微”。“熹”是微明，“微”是细小。', ejemplo: '晨光熹微，鸟叫得比人早。' },
  { palabra: '暮色', clase: '名词', definicion: '日落之后、天还没完全黑透时那层灰蓝色的光。', origen: '“暮”的古字是太阳落进草丛里，本就是傍晚的意思；“色”在这里指光的颜色，而不是事物。', ejemplo: '暮色四合的时候，山的轮廓最好看。' },
  { palabra: '涟漪', clase: '名词', definicion: '水面被轻轻惊动后，一圈圈荡开的细纹。', origen: '《诗经·魏风·伐檀》有“河水清且涟猗”。后来也用来说心里被触动的那一下。', ejemplo: '一片叶子落下去，池面起了一层涟漪。' },
  { palabra: '清欢', clase: '名词', definicion: '从简单的事物里得到的、不喧闹的快乐。', origen: '苏轼《浣溪沙》的“人间有味是清欢”，说的是野菜清茶也能让人满足，与热闹的欢乐正好相对。', ejemplo: '一碗热汤面，两页闲书，也算清欢。' },
  { palabra: '光风霁月', clase: '成语', definicion: '雨过天晴后的清朗景象，也用来说一个人胸怀坦荡。', origen: '黄庭坚形容周敦颐“胸中洒落，如光风霁月”。“霁”是雨雪停歇，天由阴转晴。', ejemplo: '他做事光风霁月，从不背后议论人。' },
  { palabra: '澄澈', clase: '形容词', definicion: '清亮见底，没有一点浑浊。', origen: '“澄”是让浑水静下来沉淀，“澈”是通到底。既说水，也说眼神和心思。', ejemplo: '高原上的湖水澄澈得能数清石头。' },
  { palabra: '疏影', clase: '名词', definicion: '稀疏的枝影，尤其指梅花投在墙上或水里的影子。', origen: '林逋《山园小梅》的“疏影横斜水清浅，暗香浮动月黄昏”，一句话定下了后世写梅的调子。', ejemplo: '月亮出来，窗纸上落了一片疏影。' },
  { palabra: '云卷云舒', clase: '成语', definicion: '云聚了又散，散了又聚；比喻从容看待起落。', origen: '出自明代洪应明《菜根谭》的“宠辱不惊，闲看庭前花开花落；去留无意，漫随天外云卷云舒”。', ejemplo: '结果还没出来，先学着云卷云舒吧。' },
  { palabra: '望舒', clase: '名词', definicion: '神话里替月亮驾车的神，后来直接用来称月亮。', origen: '屈原《离骚》有“前望舒使先驱兮，后飞廉使奔属”。“望”是月圆之日，“舒”是缓缓展开。', ejemplo: '望舒未起，山路上只剩星光。' },
  { palabra: '星河', clase: '名词', definicion: '横过夜空的那条银河。', origen: '古人把它看作天上的一条河，牛郎织女被它隔开的故事也由此而来。“银河”“天河”说的都是同一条。', ejemplo: '关掉营地的灯，星河一下子压了下来。' },
  { palabra: '温存', clase: '动词', definicion: '用体贴的话语和动作照顾另一个人的情绪。', origen: '“温”是不冷不烫的那个分寸，“存”是慰问、问候。合起来是把人放在心上，又不去惊动他。', ejemplo: '他不太会安慰人，却懂得温存地递上一杯水。' },
  { palabra: '恬淡', clase: '形容词', definicion: '心里安静，对名利没有太多欲望。', origen: '《庄子·刻意》有“恬淡寂寞，虚无无为”。“恬”是安然，“淡”是不浓。', ejemplo: '退休以后他过得恬淡，一天只做三件事。' },
  { palabra: '徜徉', clase: '动词', definicion: '悠闲地来回走，不赶时间，也不为了到达哪里。', origen: '两个字都是双人旁，本义就是慢慢地走。既可以走在河边，也可以走在一本书里。', ejemplo: '整个下午都在旧书店里徜徉。' },
  { palabra: '婆娑', clase: '形容词', definicion: '枝叶或身影摇曳舒展的样子。', origen: '《诗经·陈风·东门之枌》里已用来形容舞姿；后来更多写树影，“树影婆娑”几乎成了固定说法。', ejemplo: '风起来，一院子的竹影婆娑。' },
  { palabra: '踟蹰', clase: '动词', definicion: '在原地徘徊，迟迟拿不定主意。', origen: '《诗经·邶风·静女》的“爱而不见，搔首踟蹰”，写的正是等不到人时抓耳挠腮的那副样子。', ejemplo: '在门口踟蹰了半天，还是没按门铃。' },
  { palabra: '阑珊', clase: '形容词', definicion: '将尽未尽，热闹正在退下去。', origen: '辛弃疾《青玉案·元夕》的“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”，让这个词从此带上了寻找的意味。', ejemplo: '散场后灯火阑珊，反倒比刚才好看。' },
  { palabra: '荼蘼', clase: '名词', definicion: '春天最后开的一种白花，它谢了就再没有花期。', origen: '“开到荼蘼花事了”出自宋人诗句。荼蘼在暮春之末才开，于是成了一段美好走到尽头的代称。', ejemplo: '院子里的荼蘼开了，今年的春天要收尾了。' },
  { palabra: '落霞', clase: '名词', definicion: '日落时天边被染红的那片云。', origen: '王勃《滕王阁序》的“落霞与孤鹜齐飞，秋水共长天一色”，一句写尽了黄昏的高远。', ejemplo: '江面上落霞铺开，船都成了剪影。' },
  { palabra: '芳菲', clase: '名词', definicion: '花草的香气与繁盛，也用来指春天本身。', origen: '白居易《大林寺桃花》有“人间四月芳菲尽，山寺桃花始盛开”。“芳”是香，“菲”是茂密。', ejemplo: '山下芳菲已尽，山上才刚刚开始。' },
  { palabra: '韶光', clase: '名词', definicion: '明媚的春光，也用来说人一生中最好的那些年。', origen: '“韶”本是舜时的乐名，孔子听了三月不知肉味，这个字于是带上了美好的意思。', ejemplo: '别辜负了韶光，想做的事就去做。' },
  { palabra: '岑寂', clase: '形容词', definicion: '又高又静，静到有点孤单。', origen: '“岑”是小而高的山。站在高处四下无人，那种安静比平地上的安静更深一层。', ejemplo: '冬夜的车站岑寂，只有一盏灯亮着。' },
  { palabra: '悠然', clase: '形容词', definicion: '从容自在，不慌不忙。', origen: '陶渊明《饮酒》的“采菊东篱下，悠然见南山”，这两个字几乎成了他这个人的注脚。', ejemplo: '他悠然地泡好茶，才开始说正事。' },
  { palabra: '相思', clase: '名词', definicion: '彼此想念却不在一处的那份牵挂。', origen: '王维《相思》写红豆“愿君多采撷，此物最相思”，红豆从此叫作相思子。', ejemplo: '一封信要走半个月，剩下的日子都是相思。' },
  { palabra: '潸然', clase: '副词', definicion: '眼泪不由自主流下来的样子。', origen: '《诗经·小雅·大东》有“潸焉出涕”。这个字从水，写的是无声落泪，而不是放声大哭。', ejemplo: '看到最后一页，他潸然泪下。' },
  { palabra: '白驹过隙', clase: '成语', definicion: '时间过得极快，像白马从一道缝隙前一闪而过。', origen: '《庄子·知北游》的“人生天地之间，若白驹之过郤，忽然而已”。“郤”同“隙”，是墙上的缝。', ejemplo: '一转眼孩子就上中学了，真是白驹过隙。' },
  { palabra: '蓦然', clase: '副词', definicion: '冷不防地，事先毫无准备。', origen: '“蓦”的本义是翻身上马，动作快而突然，后来引申为忽然。', ejemplo: '蓦然想起还有一件事没做。' },
  { palabra: '桑梓', clase: '名词', definicion: '故乡。', origen: '《诗经·小雅·小弁》有“维桑与梓，必恭敬止”。古人在屋前屋后种桑树和梓树，见到它们就想起父母，于是用来代指家乡。', ejemplo: '离开桑梓三十年，口音还没改。' },
]

const PALABRAS_KO: Palabra[] = [
  { palabra: '그리움', clase: '명사', definicion: '곁에 없는 사람이나 지나간 때가 사무치게 보고 싶은 마음이에요.', origen: '‘그리다’에서 나온 말이에요. 마음속으로 대상을 그린다는 뜻이 그대로 이름이 되었어요.', ejemplo: '오래된 사진을 넘기다 보면 그리움이 먼저 도착해요.' },
  { palabra: '달무리', clase: '명사', definicion: '달 둘레에 뿌옇게 생기는 둥근 빛의 테두리예요.', origen: '‘달’에 테두리를 뜻하는 ‘무리’가 붙었어요. 달무리가 서면 이튿날 비가 온다는 말이 오래 전해져 왔어요.', ejemplo: '달무리가 크게 섰으니 우산을 챙기는 게 좋겠어요.' },
  { palabra: '윤슬', clase: '명사', definicion: '햇빛이나 달빛이 물결 위에서 잘게 반짝이는 모습이에요.', origen: '순우리말이에요. ‘물비늘’이라고도 하는데, 윤슬 쪽이 더 부드럽게 들려서 이름으로도 자주 쓰여요.', ejemplo: '다리 위에서 강을 보면 윤슬이 종일 흔들려요.' },
  { palabra: '미리내', clase: '명사', definicion: '은하수를 가리키는 순우리말이에요.', origen: '옛말 ‘미르(용)’와 ‘내(시내)’가 합쳐진 말로, 용이 사는 하늘의 시내라는 뜻이에요.', ejemplo: '불을 다 끄자 미리내가 머리 위로 쏟아졌어요.' },
  { palabra: '도담도담', clase: '부사', definicion: '아이가 별 탈 없이 잘 자라는 모습이에요.', origen: '탐스럽고 오붓하다는 뜻의 ‘도담하다’를 겹쳐 만든 말이에요. 반복이 주는 리듬이 자라는 속도를 닮았어요.', ejemplo: '작년에 심은 나무가 도담도담 자라고 있어요.' },
  { palabra: '시나브로', clase: '부사', definicion: '모르는 사이에 조금씩이라는 뜻이에요.', origen: '옛 문헌에도 나오는 순우리말로, 한꺼번에 오지 않고 자기도 모르게 쌓이는 변화를 가리켜요.', ejemplo: '시나브로 해가 길어져서 저녁이 환해요.' },
  { palabra: '고즈넉하다', clase: '형용사', definicion: '조용하고 아늑하면서 쓸쓸한 맛이 살짝 도는 상태예요.', origen: '고요히를 뜻하는 옛말 ‘고즈너기’에서 왔어요. 시끄럽지 않다는 뜻만이 아니라, 그 조용함이 마음에 든다는 뜻까지 담고 있어요.', ejemplo: '비 오는 날의 절 마당은 유난히 고즈넉해요.' },
  { palabra: '호젓하다', clase: '형용사', definicion: '사람이 없어 조용하면서도 혼자 있기에 좋은 느낌이에요.', origen: '무섭도록 외지다는 뜻과 홀가분하다는 뜻을 함께 가진 말이라, 같은 자리도 마음에 따라 다르게 읽혀요.', ejemplo: '호젓한 산길을 한 시간쯤 혼자 걸었어요.' },
  { palabra: '애틋하다', clase: '형용사', definicion: '안타깝고 아쉬우면서도 정이 깊게 남는 마음이에요.', origen: '마음을 뜻하는 ‘애’가 탈 만큼 절실하다는 데서 나왔다고 봐요. 슬픔과 사랑이 한데 섞인 자리를 가리켜요.', ejemplo: '짧게 스친 사이라 더 애틋해요.' },
  { palabra: '사부작사부작', clase: '부사', definicion: '힘들이지 않고 조용조용 무언가를 해 나가는 모습이에요.', origen: '‘사부랑사부랑’과 뿌리를 나눈 말로, 소리도 동작도 크지 않다는 점이 핵심이에요.', ejemplo: '주말 아침에 사부작사부작 방을 치웠어요.' },
  { palabra: '여울', clase: '명사', definicion: '강이나 개울에서 바닥이 얕아 물살이 빨라지는 곳이에요.', origen: '순우리말이에요. 여기서 물소리가 커지기 때문에 ‘여울목’은 눈보다 귀로 먼저 알아채는 자리이기도 해요.', ejemplo: '여울을 건널 때는 신발을 벗는 편이 나아요.' },
  { palabra: '산들바람', clase: '명사', definicion: '시원하고 부드럽게 부는 바람이에요.', origen: '흉내말 ‘산들산들’에 ‘바람’이 붙었어요. 기상 용어로는 초속 3.4~5.4미터의 바람을 가리켜요.', ejemplo: '창을 열자 산들바람이 커튼을 들었어요.' },
  { palabra: '물마루', clase: '명사', definicion: '먼바다에서 하늘과 맞닿아 보이는 물결의 꼭대기예요.', origen: '‘물’에 산꼭대기를 뜻하는 ‘마루’가 붙었어요. 바다에도 능선이 있다고 본 셈이에요.', ejemplo: '배는 물마루 너머로 천천히 사라졌어요.' },
  { palabra: '해거름', clase: '명사', definicion: '해가 서쪽으로 기울어 곧 지려는 무렵이에요.', origen: '‘해’와 기운다는 뜻의 ‘거름’이 만난 말이에요. 아직 어둡지는 않지만 하루가 접히기 시작하는 시간이에요.', ejemplo: '해거름에 마당에 물을 뿌리면 흙 냄새가 올라와요.' },
  { palabra: '어스름', clase: '명사', definicion: '조금 어둑한 빛. 날이 밝기 직전이나 저문 직후의 흐릿함이에요.', origen: '‘어슴푸레하다’와 뿌리가 같아요. 완전한 어둠이 아니라 아직 형체가 보이는 정도라는 점이 중요해요.', ejemplo: '새벽 어스름에 길을 나섰어요.' },
  { palabra: '아지랑이', clase: '명사', definicion: '봄날 땅에서 올라오는 더운 공기 때문에 경치가 일렁여 보이는 현상이에요.', origen: '순우리말이에요. 실제로 무엇이 있는 것은 아니어서, 잡히지 않는 것을 비유할 때도 써요.', ejemplo: '아스팔트 위로 아지랑이가 피어올랐어요.' },
  { palabra: '소복소복', clase: '부사', definicion: '눈이나 먼지가 소리 없이 도톰하게 쌓이는 모습이에요.', origen: '수북하다는 뜻의 ‘소복하다’를 겹친 말이에요. 겹쳐 쓰면 쌓이는 과정이 느리다는 느낌까지 살아나요.', ejemplo: '밤새 눈이 소복소복 내려앉았어요.' },
  { palabra: '함초롬하다', clase: '형용사', definicion: '젖은 듯이 촉촉하면서 가지런하고 곱다는 뜻이에요.', origen: '이슬 맞은 풀이나 머리카락처럼, 물기와 단정함이 함께 있는 상태를 가리켜요.', ejemplo: '비를 맞은 잎들이 함초롬해요.' },
  { palabra: '곰비임비', clase: '부사', definicion: '좋은 일이 자꾸 겹쳐서 일어나는 모습이에요.', origen: '물건이 거듭 포개진다는 뜻의 옛말에서 왔어요. 나쁜 일에는 잘 쓰지 않는다는 점이 이 말의 성격이에요.', ejemplo: '올해는 반가운 소식이 곰비임비 들어와요.' },
  { palabra: '애오라지', clase: '부사', definicion: '겨우, 또는 오직이라는 뜻이에요.', origen: '적다는 뜻과 오로지라는 뜻을 함께 가진 옛말이에요. ‘가진 게 이것뿐’과 ‘이것 하나만은’이 한 낱말 안에 들어 있어요.', ejemplo: '애오라지 이 한 가지만 지키기로 했어요.' },
  { palabra: '마음결', clase: '명사', definicion: '마음이 지닌 바탕이나 결. 그 사람의 성품이 드러나는 무늬예요.', origen: '나무의 ‘결’을 마음으로 옮겨 온 말이에요. 겉으로는 보이지 않아도 잘라 보면 드러난다는 뜻이 숨어 있어요.', ejemplo: '마음결이 고운 사람은 말끝이 달라요.' },
  { palabra: '뒤안길', clase: '명사', definicion: '집 뒤의 좁은 길. 나아가 화려한 곳에서 비켜난 삶의 자리예요.', origen: '뒤꼍을 뜻하는 ‘뒤안’과 ‘길’이 만난 말이에요. 서정주의 시에 쓰인 뒤로 비유의 뜻이 더 널리 퍼졌어요.', ejemplo: '역사의 뒤안길에도 사람은 살고 있었어요.' },
  { palabra: '오롯이', clase: '부사', definicion: '모자람 없이 온전하게, 고스란히라는 뜻이에요.', origen: '온전하다는 뜻의 ‘오롯하다’에서 왔어요. 나누지 않고 통째로라는 뉘앙스가 핵심이에요.', ejemplo: '오늘 저녁은 오롯이 나를 위해 쓰기로 했어요.' },
  { palabra: '살갑다', clase: '형용사', definicion: '대하는 태도가 따뜻하고 상냥해요.', origen: '본래는 겉보기보다 속이 넓다는 뜻이었어요. 집을 두고도 살갑다고 했는데, 지금은 사람 사이에 주로 써요.', ejemplo: '처음 본 사이인데도 살갑게 말을 걸어 줬어요.' },
  { palabra: '뭉근하다', clase: '형용사', definicion: '불이 세지 않게 은근히 오래 끓는 상태예요.', origen: '부엌에서 나온 말이지만, 크지 않은 통증이나 오래가는 마음에도 그대로 옮겨 써요.', ejemplo: '뭉근하게 끓인 국이 제일 깊어요.' },
  { palabra: '나부시', clase: '부사', definicion: '소리 없이 부드럽게 내려앉거나 고개를 숙이는 모습이에요.', origen: '‘나부끼다’와 뿌리를 나눈 말이에요. 무게가 느껴지지 않는 동작에 써요.', ejemplo: '꽃잎이 물 위에 나부시 내려앉았어요.' },
  { palabra: '볕뉘', clase: '명사', definicion: '그늘 사이로 잠깐 비쳐 드는 작은 햇빛이에요.', origen: '‘볕’에 작은 조각을 뜻하는 ‘뉘’가 붙었어요. 남에게서 받는 작은 도움을 가리킬 때도 써요.', ejemplo: '창틈으로 든 볕뉘가 딱 한 뼘이었어요.' },
  { palabra: '물너울', clase: '명사', definicion: '바다에서 크고 느리게 굽이치는 물결이에요.', origen: '‘물’과 크게 움직인다는 뜻의 ‘너울’이 합쳐졌어요. 잔물결인 윤슬과는 규모가 아주 달라요.', ejemplo: '바람이 멎어도 물너울은 한참 남아 있었어요.' },
  { palabra: '가붓하다', clase: '형용사', definicion: '들었을 때 기분이 좋을 만큼 가벼워요.', origen: '‘가볍다’의 작은말이에요. 짐에도 쓰고, 걱정을 덜어 낸 마음에도 써요.', ejemplo: '짐을 반으로 줄이니 발걸음이 가붓해요.' },
  { palabra: '여미다', clase: '동사', definicion: '옷깃이나 매무새를 바로잡아 단정하게 해요.', origen: '옷에서 시작했지만 ‘마음을 여미다’처럼 흐트러진 것을 다잡는다는 뜻으로 넓어졌어요.', ejemplo: '바람이 차서 외투를 여미었어요.' },
  { palabra: '다독이다', clase: '동사', definicion: '가볍게 두드려 어루만지며 마음을 가라앉혀 줘요.', origen: '흙이나 이불을 두드려 고르게 만든다는 뜻에서 사람의 마음으로 옮겨 왔어요.', ejemplo: '아무 말 없이 등을 다독여 주었어요.' },
  { palabra: '아우르다', clase: '동사', definicion: '여럿을 한데 모아 하나가 되게 해요.', origen: '‘어우르다’와 한 뿌리예요. 섞어서 없애는 것이 아니라 각각을 둔 채로 묶는다는 뜻이에요.', ejemplo: '세대를 아우르는 자리라 이야기가 길어졌어요.' },
  { palabra: '여물다', clase: '동사', definicion: '곡식이나 열매가 속이 꽉 차게 익어요.', origen: '곡식에서 시작해 사람에게도 써요. ‘생각이 여물다’라고 하면 시간을 들여 단단해졌다는 뜻이에요.', ejemplo: '계획이 여물 때까지 조금 더 기다리기로 했어요.' },
  { palabra: '서리서리', clase: '부사', definicion: '긴 것을 둥글게 사려서 겹겹이 포개 놓은 모습이에요.', origen: '황진이의 시조 ‘동짓달 기나긴 밤을 한 허리를 베어 내어’에 나오는 서리서리로 널리 알려졌어요. 밤 시간을 실처럼 감아 둔다는 발상이에요.', ejemplo: '하고 싶은 말을 서리서리 담아 두었어요.' },
  { palabra: '하염없이', clase: '부사', definicion: '끝이 보이지 않게, 아무 생각 없이 계속이라는 뜻이에요.', origen: '하는 일을 뜻하는 ‘하염’이 없다는 데서 왔어요. 무엇을 하려는 뜻 없이 이어진다는 게 본래 뜻이에요.', ejemplo: '창밖을 하염없이 바라보다 밤이 되었어요.' },
  { palabra: '애면글면', clase: '부사', definicion: '힘에 부치는 일을 안간힘을 다해 해내는 모습이에요.', origen: '두 낱말을 겹쳐 만든 말로, 넉넉하지 않은 힘으로 애쓴다는 뉘앙스가 담겨 있어요.', ejemplo: '애면글면 모은 돈으로 첫 가게를 열었어요.' },
  { palabra: '갈무리', clase: '명사', definicion: '뒤에 쓰려고 잘 정리해 두는 일이에요.', origen: '곡식을 거두어 간수한다는 농사 말에서 왔어요. 지금은 파일을 저장하는 일에도 그대로 써요.', ejemplo: '오늘 찍은 사진은 저녁에 갈무리해 둘게요.' },
  { palabra: '너나들이', clase: '명사', definicion: '서로 너, 나 하고 부를 만큼 허물없는 사이예요.', origen: '‘너’와 ‘나’에 오간다는 뜻의 ‘들이’가 붙었어요. 높임말을 내려놓는 순간을 아예 관계의 이름으로 삼은 셈이에요.', ejemplo: '일 년 만에 너나들이하는 사이가 되었어요.' },
  { palabra: '눈부처', clase: '명사', definicion: '남의 눈동자에 비쳐 보이는 아주 작은 내 모습이에요.', origen: '눈동자 속에 앉은 그 형상이 부처를 닮았다고 해서 붙은 이름이에요.', ejemplo: '가까이서 보니 눈부처가 또렷했어요.' },
  { palabra: '도란도란', clase: '부사', definicion: '여럿이 나직하고 정답게 이야기하는 소리나 모습이에요.', origen: '목소리를 낮춘 대화를 흉내 낸 말이에요. 크게 떠드는 ‘왁자지껄’과 정확히 반대편에 있어요.', ejemplo: '늦게까지 도란도란 이야기하다 잠들었어요.' },
]

// Palabras RUSAS, no traducciones: «петрикор» no existe en ruso y «серендипность»
// es una transcripción sin gracia. Se han cruzado antes con `dict.ru.ts` para no
// repetir un término que el usuario ya lee en la interfaz (por eso no está «уют»,
// que es el nombre del ambiente musical «acogedor»).
const PALABRAS_RU: Palabra[] = [
  { palabra: 'Обаяние', clase: 'существительное', definicion: 'Притягательная сила человека, которую невозможно объяснить, но которой невозможно и сопротивляться.', origen: 'От старого «баять» — говорить, заговаривать. Обаятельный человек буквально «заговаривает» тебя словом, как знахарь.', ejemplo: 'Он не сказал ничего особенного, но всё держалось на его обаянии.' },
  { palabra: 'Простор', clase: 'существительное', definicion: 'Свободное, ничем не стеснённое пространство, которое хочется вдохнуть.', origen: 'От того же корня, что «простереться» — раскинуться. Родня «пространству», но у простора есть чувство, которого у пространства нет.', ejemplo: 'Вышли из леса — и впереди открылся простор до самой реки.' },
  { palabra: 'Задушевность', clase: 'существительное', definicion: 'Теплота разговора, в котором говорят прямо от души и без брони.', origen: 'От «за душой»: то, что человек держит за душой и достаёт только для своих.', ejemplo: 'Разговор на кухне до трёх ночи — вот вся задушевность.' },
  { palabra: 'Тоска', clase: 'существительное', definicion: 'Тяжёлая тихая грусть без ясной причины; томление по чему-то, чего не назвать.', origen: 'От древнерусского «тъска» — стеснение, теснота в груди. Ни на один язык не переводится одним словом: приходится объяснять.', ejemplo: 'К вечеру подступила тоска, и он вышел пройтись.' },
  { palabra: 'Умиление', clase: 'существительное', definicion: 'Тихая нежность, от которой теплеет в груди и щиплет глаза.', origen: 'От старославянского «умилити» — смягчить сердце. Слово пришло из молитвы и осталось в обычной жизни.', ejemplo: 'Он смотрел на спящего кота с умилением.' },
  { palabra: 'Трепет', clase: 'существительное', definicion: 'Лёгкая дрожь от волнения, восхищения или страха.', origen: 'Звукоподражательное, от «трепетать» — часто и мелко дрожать, как лист на ветру.', ejemplo: 'Она открыла старый конверт с трепетом.' },
  { palabra: 'Упоение', clase: 'существительное', definicion: 'Состояние, когда захватывает целиком и ничего вокруг уже не замечаешь.', origen: 'От «упиться» — напиться допьяна. Только пьянеешь не от вина, а от счастья, музыки или скорости.', ejemplo: 'Он пел в упоении, забыв половину слов.' },
  { palabra: 'Нега', clase: 'существительное', definicion: 'Сладкая расслабленность: тепло, покой и ни одной заботы.', origen: 'Древнее славянское слово, родня «нежному». Раньше значило заботу и холю, а осталась одна разнеженность.', ejemplo: 'После бани его разморило, и он лежал в неге.' },
  { palabra: 'Отрада', clase: 'существительное', definicion: 'То, что радует и утешает; тихая радость посреди будней.', origen: 'От «радовать» с приставкой от-: то, что отводит печаль.', ejemplo: 'Утренний кофе у окна — вся его отрада.' },
  { palabra: 'Шелест', clase: 'существительное', definicion: 'Тихий шорох листьев, страниц или платья.', origen: 'Звукоподражание: слово само шелестит, когда его произносишь.', ejemplo: 'В саду стоял только шелест тополей.' },
  { palabra: 'Марево', clase: 'существительное', definicion: 'Дрожащее колебание воздуха от жары, из-за которого даль плывёт.', origen: 'Одного корня с «марой» — наваждением, призраком. Отсюда же «мираж»: то, чего на самом деле нет.', ejemplo: 'Над раскалённым шоссе стояло марево.' },
  { palabra: 'Окоём', clase: 'существительное', definicion: 'Всё, что охватывает глаз; горизонт.', origen: 'Буквально «то, что око ёмлет» — берёт, вмещает. Старое слово, которое поэты вернули из забвения.', ejemplo: 'На окоёме показалась полоска дождя.' },
  { palabra: 'Заводь', clase: 'существительное', definicion: 'Тихий залив у берега реки, где вода почти не движется.', origen: 'От «завести»: вода заводит сюда и останавливается. О человеке говорят так же — «нашёл свою тихую заводь».', ejemplo: 'Лодку оставили в заводи под ивами.' },
  { palabra: 'Полынья', clase: 'существительное', definicion: 'Незамерзающее окно чистой воды посреди льда.', origen: 'Того же корня, что «полый» — пустой: дыра в ледяном поле.', ejemplo: 'У полыньи собрались утки, которые не улетели.' },
  { palabra: 'Капель', clase: 'существительное', definicion: 'Звонкая капля с крыш, когда снег начинает таять.', origen: 'От «капать». Это ещё и звук: капель слышно раньше, чем видно весну.', ejemplo: 'С утра за окном стучала капель.' },
  { palabra: 'Изморозь', clase: 'существительное', definicion: 'Тонкий белый иней, который за ночь оседает на ветках.', origen: 'От «мороза» с приставкой из-. Не путай с «изморосью»: та — мелкий дождь, и пишется через «с».', ejemplo: 'К утру всё стояло в изморози.' },
  { palabra: 'Позёмка', clase: 'существительное', definicion: 'Снег, который метёт понизу, не поднимаясь выше колена.', origen: 'От «по земле». Русский различает метель, вьюгу, пургу и позёмку — по тому, где именно летит снег.', ejemplo: 'Ветер гнал позёмку через пустую дорогу.' },
  { palabra: 'Звездопад', clase: 'существительное', definicion: 'Ночь, когда падают метеоры и небо будто осыпается.', origen: 'Сложение «звезды» и «падать», по образцу «листопада».', ejemplo: 'В августе поехали за город смотреть звездопад.' },
  { palabra: 'Посиделки', clase: 'существительное', definicion: 'Долгое неспешное сидение вместе — с чаем, разговором и без всякого повода.', origen: 'От «посидеть». Так называли зимние вечера, на которых пряли и пели; повод отпал, а слово осталось.', ejemplo: 'Посиделки затянулись за полночь.' },
  { palabra: 'Раздолье', clase: 'существительное', definicion: 'Широкий простор, где ничто не мешает; полная воля.', origen: 'От «дола» — долины, с приставкой раз-: земля, раскинувшаяся во все стороны.', ejemplo: 'Летом у реки детям раздолье.' },
  { palabra: 'Удаль', clase: 'существительное', definicion: 'Смелость с размахом — весёлая и немного бесшабашная.', origen: 'От «удаться»: удалой — тот, кому удаётся. От храбрости отличается тем, что в удали всегда есть азарт.', ejemplo: 'В его удали было больше радости, чем расчёта.' },
  { palabra: 'Наитие', clase: 'существительное', definicion: 'Догадка, которая приходит сама, без рассуждений.', origen: 'От старого «наити» — найти, найти на кого-то. Раньше так говорили о вдохновении свыше.', ejemplo: 'Он свернул в переулок по наитию и не ошибся.' },
  { palabra: 'Послевкусие', clase: 'существительное', definicion: 'След, который остаётся после вкуса, разговора или книги.', origen: 'Сложение «после» и «вкуса». Слово пришло из дегустации и разошлось на всё, что оставляет след.', ejemplo: 'У этого фильма долгое светлое послевкусие.' },
  { palabra: 'Предвкушение', clase: 'существительное', definicion: 'Радость от того, что хорошее ещё только будет.', origen: 'От «пред-» и «вкушать» — пробовать заранее. Часто оказывается вкуснее самого события.', ejemplo: 'Вся неделя прошла в предвкушении поездки.' },
  { palabra: 'Глухомань', clase: 'существительное', definicion: 'Далёкое глухое место, куда не доходит ни дорога, ни шум.', origen: 'От «глухого» — беззвучного и непроходимого: там, где лес глушит всё.', ejemplo: 'Дом стоял в такой глухомани, что телефон не ловил.' },
  { palabra: 'Затишье', clase: 'существительное', definicion: 'Пауза, когда всё стихло: перед бурей или сразу после неё.', origen: 'От «тихо» с приставкой за-. Погоду и жизнь русский описывает здесь одними словами.', ejemplo: 'В августе на работе всегда затишье.' },
  { palabra: 'Хлебосольство', clase: 'существительное', definicion: 'Щедрое гостеприимство, при котором стол ломится, а гостя не отпускают.', origen: 'От «хлеба» и «соли»: тем, что дороже всего, и встречали на пороге.', ejemplo: 'Их хлебосольство переживёт любые времена.' },
  { palabra: 'Созерцание', clase: 'существительное', definicion: 'Долгое спокойное разглядывание без всякой цели что-то сделать.', origen: 'От старого «зерцати» — смотреть; того же корня, что «зеркало» и «зоркий».', ejemplo: 'Полчаса созерцания реки — и голова снова ясная.' },
  { palabra: 'Сокровенный', clase: 'прилагательное', definicion: 'Самый близкий и потаённый, о котором не говорят вслух.', origen: 'От «сокрыть». Родня «сокровищу»: и то и другое прячут.', ejemplo: 'Он рассказал ей самое сокровенное.' },
  { palabra: 'Заветный', clase: 'прилагательное', definicion: 'Тот, который берегут и о котором давно мечтают.', origen: 'От «завета» — обещания, наказа. Заветное — то, что как будто обещано самому себе.', ejemplo: 'Он достал заветную коробку с письмами.' },
  { palabra: 'Безмятежный', clase: 'прилагательное', definicion: 'Спокойный до полной ясности, без единой тревоги.', origen: 'От «без» и «мятеж»: буквально «без бунта» — ни ветра снаружи, ни смуты внутри.', ejemplo: 'Море было безмятежным до самого вечера.' },
  { palabra: 'Лучезарный', clase: 'прилагательное', definicion: 'Сияющий, испускающий лучи; о лице — светящийся радостью.', origen: 'Сложение «луча» и «зари».', ejemplo: 'Она вошла с лучезарной улыбкой.' },
  { palabra: 'Первозданный', clase: 'прилагательное', definicion: 'Такой, каким был в самом начале, ещё никем не тронутый.', origen: 'От «первый» и «созданный» — созданный первым, в день творения.', ejemplo: 'В горах сохранилась первозданная тишина.' },
  { palabra: 'Мимолётный', clase: 'прилагательное', definicion: 'Промелькнувший и исчезнувший; очень короткий.', origen: 'От «мимо» и «лететь»: то, что пролетело мимо и не задержалось.', ejemplo: 'Между ними был мимолётный взгляд — и всё.' },
  { palabra: 'Окрылённый', clase: 'прилагательное', definicion: 'Тот, кому что-то придало сил, будто выросли крылья.', origen: 'От «крыла». Удачу русский описывает как прибавление крыльев, а неудачу — как опущенные руки.', ejemplo: 'После разговора он вышел окрылённым.' },
  { palabra: 'Лелеять', clase: 'глагол', definicion: 'Бережно растить и баловать заботой; долго хранить в себе мечту.', origen: 'Древнее слово с удвоением, как в колыбельном «люли-люли»: в самом звуке слышно укачивание.', ejemplo: 'Он лелеял эту мысль много лет.' },
  { palabra: 'Любоваться', clase: 'глагол', definicion: 'Смотреть на что-то с удовольствием, ничего больше не желая.', origen: 'От «любо» — приятно, хорошо; того же корня, что «любовь».', ejemplo: 'Они долго любовались закатом с моста.' },
  { palabra: 'Ворковать', clase: 'глагол', definicion: 'Тихо и нежно разговаривать вдвоём, как голуби.', origen: 'Звукоподражание голубиному «вор-вор». О влюблённых говорят теми же словами, что о птицах.', ejemplo: 'Они ворковали в углу весь вечер.' },
  { palabra: 'Исподволь', clase: 'наречие', definicion: 'Понемногу и незаметно, без всякого нажима.', origen: 'Восходит к сочетанию «из-под воли»: как бы помимо собственной воли, само собой.', ejemplo: 'Исподволь он приучил себя вставать раньше.' },
  { palabra: 'Невзначай', clase: 'наречие', definicion: 'Случайно, не нарочно; как бы между делом.', origen: 'От старого «чаять» — ожидать: то, чего не ожидали. Говорят так чаще всего как раз тогда, когда умысел был.', ejemplo: 'Она невзначай спросила про его планы.' },
]

// Palabras HINDIS de verdad, no traducidas: mezcla de voces sánscritas (गोधूलि,
// मृगतृष्णा), persoárabes de la vena urdu (तन्हाई, इत्मीनान, शबनम) y deshi de a pie
// (झुरमुट, पनघट, रिमझिम). Cruzadas antes con `dict.hi.ts`: por eso no están सुकून
