// Las citas van en el registro aforístico ruso, no en el «ты» de la interfaz:
// donde existe traducción asentada se usa esa (Sócrates, Séneca, Beauvoir, y el
// Saint-Exupéry de Nora Gal, que en ruso se cita siempre igual). `wiki` y `autor`
// coinciden porque la Wikipedia rusa redirige desde el orden natural; la excepción
// vuelve a ser Isabel Allende, cuyo nombre natural es una desambiguación.
const FRASES_RU: { cita: string; wiki?: string; autor?: string }[] = [
  { cita: 'Жизнь — это не то, что человек прожил, а то, что он помнит и как он это помнит, чтобы рассказать.', wiki: 'Габриэль Гарсиа Маркес', autor: 'Габриэль Гарсиа Маркес' },
  { cita: 'Кто много читает и много ходит, тот много видит и много знает.', wiki: 'Мигель де Сервантес', autor: 'Мигель де Сервантес' },
  { cita: 'Я всегда представлял себе рай чем-то вроде библиотеки.', wiki: 'Хорхе Луис Борхес', autor: 'Хорхе Луис Борхес' },
  { cita: 'Зачем мне ноги, если у меня есть крылья, чтобы летать?', wiki: 'Фрида Кало', autor: 'Фрида Кало' },
  { cita: 'Воображение важнее знания.', wiki: 'Альберт Эйнштейн', autor: 'Альберт Эйнштейн' },
  { cita: 'В жизни нет ничего, чего следовало бы бояться, — есть лишь то, что нужно понять.', wiki: 'Мария Склодовская-Кюри', autor: 'Мария Склодовская-Кюри' },
  { cita: 'Я знаю только то, что ничего не знаю.', wiki: 'Сократ', autor: 'Сократ' },
  { cita: 'Мы есть то, что мы постоянно делаем. Совершенство, следовательно, не действие, а привычка.', wiki: 'Аристотель', autor: 'Аристотель' },
  { cita: 'Мы располагаем не малым временем, а теряем много.', wiki: 'Луций Анней Сенека', autor: 'Сенека' },
  { cita: 'Счастье твоей жизни зависит от качества твоих мыслей.', wiki: 'Марк Аврелий', autor: 'Марк Аврелий' },
  { cita: 'Выбери работу по душе — и тебе не придётся работать ни дня в жизни.', wiki: 'Конфуций', autor: 'Конфуций' },
  { cita: 'Будь тем изменением, которое ты хочешь видеть в мире.', wiki: 'Махатма Ганди', autor: 'Махатма Ганди' },
  { cita: 'Всё кажется невозможным, пока не будет сделано.', wiki: 'Нельсон Мандела', autor: 'Нельсон Мандела' },
  { cita: 'Сделай первый шаг с верой. Необязательно видеть всю лестницу целиком.', wiki: 'Мартин Лютер Кинг', autor: 'Мартин Лютер Кинг' },
  { cita: 'Лучший способ предсказать будущее — изобрести его.', wiki: 'Алан Кэй', autor: 'Алан Кэй' },
  { cita: 'Если ты можешь об этом мечтать, ты можешь это сделать.', wiki: 'Уолт Дисней', autor: 'Уолт Дисней' },
  { cita: 'Никто не может заставить тебя чувствовать себя ничтожеством без твоего согласия.', wiki: 'Элеонора Рузвельт', autor: 'Элеонора Рузвельт' },
  { cita: 'Женщиной не рождаются, женщиной становятся.', wiki: 'Симона де Бовуар', autor: 'Симона де Бовуар' },
  { cita: 'Нет ни преграды, ни замка, ни засова, которые можно было бы наложить на свободу моего разума.', wiki: 'Вирджиния Вулф', autor: 'Вирджиния Вулф' },
  { cita: 'Секрет того, как двинуться вперёд, — начать.', wiki: 'Марк Твен', autor: 'Марк Твен' },
  { cita: 'Будь собой — остальные роли уже заняты.', wiki: 'Оскар Уайльд', autor: 'Оскар Уайльд' },
  { cita: 'Зорко одно лишь сердце. Самого главного глазами не увидишь.', wiki: 'Антуан де Сент-Экзюпери', autor: 'Антуан де Сент-Экзюпери' },
  { cita: 'Между людьми, как и между народами, уважение к чужому праву есть мир.', wiki: 'Бенито Хуарес', autor: 'Бенито Хуарес' },
  { cita: 'Родина — это алтарь, а не пьедестал.', wiki: 'Хосе Марти', autor: 'Хосе Марти' },
  { cita: 'Путник, дороги нет: дорога прокладывается в пути.', wiki: 'Антонио Мачадо', autor: 'Антонио Мачадо' },
  { cita: 'Поэзия — это чувство, которое не умещается в сердце и выходит через руку.', wiki: 'Федерико Гарсиа Лорка', autor: 'Федерико Гарсиа Лорка' },
  { cita: 'Мы шли, не ища друг друга, но знали, что идём, чтобы встретиться.', wiki: 'Хулио Кортасар', autor: 'Хулио Кортасар' },
  { cita: 'Записывай то, что не должно быть забыто.', wiki: 'Альенде Льона, Исабель', autor: 'Исабель Альенде' },
  { cita: 'Не сдавайся, прошу тебя, не отступай, даже если холод жжёт, даже если страх кусает.', wiki: 'Марио Бенедетти', autor: 'Марио Бенедетти' },
  { cita: 'Много маленьких людей в маленьких местах, делая маленькие дела, могут изменить мир.', wiki: 'Эдуардо Галеано', autor: 'Эдуардо Галеано' },
  { cita: 'Простота — это высшая степень утончённости.', wiki: 'Леонардо да Винчи', autor: 'Леонардо да Винчи' },
  { cita: 'Я вижу во сне свою картину, а потом пишу свой сон.', wiki: 'Винсент Ван Гог', autor: 'Винсент Ван Гог' },
  { cita: 'Всё, что ты можешь вообразить, — реально.', wiki: 'Пабло Пикассо', autor: 'Пабло Пикассо' },
  { cita: 'Музыка — откровение более высокое, чем вся мудрость и вся философия.', wiki: 'Людвиг ван Бетховен', autor: 'Людвиг ван Бетховен' },
  { cita: 'Настоящее принадлежит им; будущее, ради которого я по-настоящему работал, — моё.', wiki: 'Никола Тесла', autor: 'Никола Тесла' },
  { cita: 'Мы — звёздная пыль, которая думает о звёздах.', wiki: 'Карл Саган', autor: 'Карл Саган' },
  { cita: 'То, что мы знаем, — капля, чего не знаем — океан.', wiki: 'Исаак Ньютон', autor: 'Исаак Ньютон' },
  { cita: 'Есть движущая сила мощнее пара, электричества и атомной энергии: воля.', wiki: 'Альберт Эйнштейн', autor: 'Альберт Эйнштейн' },
  { cita: 'За каждым достижением стоит следующий вызов.', wiki: 'Мать Тереза', autor: 'Мать Тереза' },
  { cita: 'Пока ты не решился окончательно, есть колебание и возможность отступить.', wiki: 'Иоганн Вольфганг фон Гёте', autor: 'Иоганн Вольфганг фон Гёте' },
]

// En hindi el aforismo se dice en «तुम», no en el «आप» con que la interfaz trata al
