// En polaco el aforismo se dice con «ty», no con el «pan/pani» de cortesía. La frase de
// Maria Skłodowska-Curie va en la forma clásica polaca, que es la lengua en que se
// educó. El nombre solo se repite cuando cambia (Sokrates, Arystoteles, Seneka, Marek
// Aureliusz, Konfucjusz, Matka Teresa); los cuarenta autores tienen artículo con
